//计算时间误差序列
Result := SysTimeRtcHighResGet(stUTC_Timestamp);        
stSYS_Timestamp := TO_ULINT(stUTC_Timestamp);           // ULINT，获取本地时间
dtNow := TO_DT(stUTC_Timestamp / 1000); 		        // 转换为DATE_AND_TIME类型

Uptriger(CLK:=Triger);                                  //检测PPS上升沿
IF Uptriger.Q THEN                                      //上升沿触发后，GPRMC解析，DO0上升沿输出（电平24V）
	Feed:=TRUE;	
	dtGNSS := TO_DT(GVL.stGNSS_Timestap / 1000); 	    // 拿到串口时间数据			                                     
	iDiffETime:=ULINT_TO_DINT(GVL.stGNSS_Timestap-dtLastGNSS);  
	dtLastGNSS:=GVL.stGNSS_Timestap;                    //缓存上一周期时间戳（ms)  
	dDelPTime:=ULINT_TO_DINT(GVL.stGNSS_Timestap - stSYS_Timestamp);       //计算误差	              
	IF iDiffETime = 1000 THEN                           //确保时间更新步进1S
		IF dDelPTime < 0 THEN                           //更新最小值
			IF dDelPTime < min_DelPTime THEN
				min_DelPTime:=dDelPTime;
				DelPTime:=min_DelPTime;                 
			END_IF		
		ELSE                                            //更新最大值
			IF dDelPTime > max_DelPTime THEN
				max_DelPTime:=dDelPTime;
				DelPTime:=max_DelPTime;
			END_IF
		END_IF	
	END_IF				    						
	iCount:=iCount+1;
	IF iCount >= 60 THEN                                //一分钟校一次时间
		GVL.dDelTime:=DelPTime;
		max_DelPTime:=0;
		min_DelPTime:=0;	
		iCount:=0;
	END_IF

END_IF
TON_F(IN:=Feed, PT:=T#100MS, Q=>,ET=>);                 //脉宽200ms（测试时延，为了在示波器看波形）
IF TON_F.Q THEN
	Feed:=FALSE;		
END_IF

(*==============================================================================
  FB: PID（位置环速度输出 PID）
  任务: Canopen 10ms（由 *_Ctrl_FB 调用）
  作用: 输入目标位置与实际位置，输出速度指令（deg/s）
  算法: 比例 + 条件积分（误差小于阈值才累积），无微分
  使用者: El_Ctrl_FB / Az_Ctrl_FB / Ti_Ctrl_FB 中的 VelPID_1/2/3
==============================================================================*)

// ----- 段：PID 使能入口 -----
IF (bPIDEnable>0) THEN //如果PID使能
	IF rTarget=rFeedback THEN
		rPIDOutput:=0;	               // 目标=反馈，输出为 0
	ELSE

		rErrorNow:=rTarget-rFeedback;  //计算当前误差 en
		rProportionNew:=rErrorNow;     //比例项

		// ----- 段：条件积分（仅在软限位内、误差小于阈值时才累积）-----
		IF rFeedback>rPosLimNegative AND rFeedback<rPosLimPositive THEN //若在软限位之内，工作时开启积分项
			IF (ABS(rTarget-rFeedback)<iThreshold) THEN//位置差小于积分阈值
				rIntegralNew:= rIntegralNew+rErrorNow; //积分项
			ELSE
				rIntegralNew:=0;
			END_IF;
		ELSE //不在软限位范围内,则积分项为0
			rIntegralNew:=0;
		END_IF

		// ----- 段：PID 求和输出 -----
		rPIDOutPut:=rKp*rProportionNew+rKi*rIntegralNew;
		rPIDtrace:=rKp*rProportionNew+rKi*rIntegralNew;

		// ----- 段：速度限幅（双向） -----
		IF rPIDOutput<(-rVelLim) THEN
			rPIDOutput:=-rVelLim;
		ELSIF rPIDOutput>rVelLim THEN
			rPIDOutput:=rVelLim;
		END_IF

		// ----- 段：超软限位时强制输出清零，防止继续向限位方向运动 -----
		IF rFeedback>rPosLimPositive AND rPIDOutput>0 THEN 
			rPIDOutput:=0;
		END_IF
		IF rFeedback<rPosLimNegative AND rPIDOutput<0 THEN
			rPIDOutput:=0;
		END_IF

		rLastError:=rErrorNow;//将当前误差赋值给上一次误差

	END_IF
ELSE//非使能清零PID各项
	rProportionNew:=0.0;
	rIntegralNew:=0.0;
	rPIDOutput:=0.0;
END_IF

