		bPort:=mPort,					//串口端口号设定
		p_brxdata:=ADR(recBuf),			//读取到的串口数据引脚为指针类型，使用ADR()指向自建数组将数据存放到数组中
		uiMaxsize:=100,					//设定最大读取长度
		EN_out=>m_out,					//串口读取功能块执行完成标志位******功能块执行完成不代表接收完成********
		uiRecSize=>recSize,				//串口接收数据长度，单位：字节，大于0时说明接收到数据可用于判断是否接收
		uierror=>m_uierror);			//串口读取功能块执行错误信息
										//从数组recBuf里取数据，解析出年、月、日、时、分、秒
		//有效判定(A)+和校验(hh),前 4bit和后 4bit的 16 进制数分别以 ASCII 码表示(0~9,A~F)，高位在前。
		IF 	recBuf[17] = 65 THEN
(*			checksum := 16#00;
			FOR sum_i:=1 TO 74 BY 1 DO
				checksum:= checksum XOR recBuf[sum_i];
			END_FOR
			high4 := (SHR(checksum, 4) AND 16#0F)+16#30;
			low4 := (checksum AND 16#0F)+16#30;
			IF recBuf[76]= high4 AND recBuf[77]= low4 THEN 
*)			IF recBuf[60] = 44 THEN // 航向角 x.x
				iYear:=BYTE_TO_INT(recBuf[65]-48)*10+BYTE_TO_INT(recBuf[66]-48)+2000;
				iMonth:=BYTE_TO_INT(recBuf[63]-48)*10+BYTE_TO_INT(recBuf[64]-48);
				iDay:=BYTE_TO_INT(recBuf[61]-48)*10+BYTE_TO_INT(recBuf[62]-48);
				iHour:=BYTE_TO_INT(recBuf[7]-48)*10+BYTE_TO_INT(recBuf[8]-48)+8;
				iMinute:=BYTE_TO_INT(recBuf[9]-48)*10+BYTE_TO_INT(recBuf[10]-48);
				iSecond:=BYTE_TO_INT(recBuf[11]-48)*10+BYTE_TO_INT(recBuf[12]-48);
			END_IF
			IF recBuf[61] = 44 THEN // 航向角 xx.x
				iYear:=BYTE_TO_INT(recBuf[66]-48)*10+BYTE_TO_INT(recBuf[67]-48)+2000;
				iMonth:=BYTE_TO_INT(recBuf[64]-48)*10+BYTE_TO_INT(recBuf[65]-48);
				iDay:=BYTE_TO_INT(recBuf[62]-48)*10+BYTE_TO_INT(recBuf[63]-48);
				iHour:=BYTE_TO_INT(recBuf[7]-48)*10+BYTE_TO_INT(recBuf[8]-48)+8;
				iMinute:=BYTE_TO_INT(recBuf[9]-48)*10+BYTE_TO_INT(recBuf[10]-48);
				iSecond:=BYTE_TO_INT(recBuf[11]-48)*10+BYTE_TO_INT(recBuf[12]-48);
			END_IF
			IF recBuf[62] = 44 THEN // 航向角 xxx.x
				iYear:=BYTE_TO_INT(recBuf[67]-48)*10+BYTE_TO_INT(recBuf[68]-48)+2000;
				iMonth:=BYTE_TO_INT(recBuf[65]-48)*10+BYTE_TO_INT(recBuf[66]-48);
				iDay:=BYTE_TO_INT(recBuf[63]-48)*10+BYTE_TO_INT(recBuf[64]-48);
				iHour:=BYTE_TO_INT(recBuf[7]-48)*10+BYTE_TO_INT(recBuf[8]-48)+8;
				iMinute:=BYTE_TO_INT(recBuf[9]-48)*10+BYTE_TO_INT(recBuf[10]-48);
				iSecond:=BYTE_TO_INT(recBuf[11]-48)*10+BYTE_TO_INT(recBuf[12]-48);
			END_IF
				// 计算时间戳		
				strDateTimeNow := CONCAT(STR1 := 'DT#', STR2 := INT_TO_STRING(iYear));
