		EN_OUT=>m_out,					//串口发送功能块执行完成标志位
		uierror=>m_uierror);			//串口发送功能块执行错误信息

	END_IF
*)	
END_IF

(*==============================================================================
  PRG: RealTimePosCal（程引实时位置计算）
  任务: Canopen 10ms
  作用:
    1. 合成 GVL.dRealTime（毫秒时间轴，供插值用 xt）
    2. 双轴程引(mode4)时，按时间对 Modbus 轨道表做三次样条插值
    3. 输出 rInterAzPos / rInterElPos → *_ctrl_1 合成 rPIDCmdPos
  时间源（GVL.bTimeSwich）:
    FALSE — GNSS: stGNSS_Timestap + 10×TimeAdd.icount
    TRUE  — 上位机 UTC: Modbus_Slave.UTC_New + 8h + 10×本地 icount
  插值输入:
    X = Modbus_Slave.aUTC_TIME[1..10]（时间结点，相对首点归一化）
    Y = Modbus_Slave.aPosCmd_1/2（俯仰/方位角度结点）
    xt = dRealTime - 8×3600×1000（转为与轨道表一致的 UTC 毫秒）
==============================================================================*)

// =============================================================================
// 段 1: 合成 GVL.dRealTime（全局毫秒时钟）
// =============================================================================

//直接从上位机拿数（UTC_New 一般为 UTC 毫秒，+8h 对齐北京时）
dRTime := modbus_slave.UTC_New + 8 * 3600 * 1000;
IF dRTime <> dLastRTime THEN
	icount := 0;
ELSE 
	icount := icount + 1;
END_IF
dLastRTime:=dRTime;

IF not GVL.bTimeSwich THEN
	GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;   // GNSS + 插值
ELSE
	GVL.dRealTime:=dRTime + 10*icount;                        // 上位机 UTC + 插值
END_IF
IF icount > 5000 THEN
	icount := 0;
END_IF
(*
GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;
*)
dtReal := TO_DT(GVL.dRealTime / 1000);
sRealTime := TO_STRING(dtReal);

// =============================================================================
// 段 2: 双轴均为程引 mode4 时 — 三次样条插值求当前俯仰/方位
// xt 减去 8×3600×1000 与轨道表 aUTC_TIME 时间基准对齐
// =============================================================================
IF Axis1Remote.iMode=4 AND Axis2Remote.iMode=4 THEN//若PTP时间锁定 且时间模式为PTP时间
		//三次样条插值

		//GVL.dRealTime:= TimeCase.stSYS_Timestamp + GVL.dDelTime + 1000 + 56; // 矫正后的时间 单位毫秒
		IF NOT GVL.bTimeSwich THEN
			GVL.dRealTime:=GVL.stGNSS_Timestap + 10*timeadd.icount;
		ELSE
			GVL.dRealTime:=dRTime + 10*icount;
		END_IF
		AzCubicInter(XModbusUL:=Modbus_Slave.aUTC_TIME,YModbus:=Modbus_Slave.aPosCmd_2,y0:=0,yn:=0,xt:=(ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),sout=>rInterAzPos,ErrCode=>iErrcode);
		ElCubicInter(XModbusUL:=Modbus_Slave.aUTC_TIME,YModbus:=Modbus_Slave.aPosCmd_1,y0:=0,yn:=0,xt:=(ULINT_TO_LREAL(GVL.dRealTime) - 8 * 3600 *1000),sout=>rInterElPos,ErrCode=>iErrcode);
		IF iErrcode>0 THEN //模块内错误代码清0 外部维持
			Error_code:=iErrcode;
		END_IF
END_IF

(* 段 3: 多项式拟合程引（Get_AZ / Get_AZ_1）整段已注释，当前未使用
   若启用: rInterAzPos = -rPolyAzPos, rInterElPos = rPolyElPos + 90
*)

(*==============================================================================
  PRG: Modbus_Slave（Modbus TCP 从站网关）
  任务: MainTask 50ms
  协议: Modbus TCP 端口 502，GCAN FB_ModbusTCP_Slave_*

  内存映射（与 GVL AT %MW 一致）:
    modbusData      AT %MW0   — 保持寄存器 HR，上位机读写（下发命令+多项式系数）
    modbusInputRegs AT %MW660 — 输入寄存器 IR，PLC 写入、上位机只读（状态上报）

  数据流:
    上位机写 HR → 本程序解析 → iMode_x/rPosCmd_x/aUTC_TIME 等
                              → SecurityCheck 写 AxisXRemote
    PLC 状态 → 打包 IR → 上位机读

  扩展自定义寄存器: 在 HR 区 modbusData[n] 增加解析/在 IR 区赋值即可
==============================================================================*)
// =============================================================================
// 段 A: Modbus TCP 从站初始化（端口 502，仅首次）
// =============================================================================
IF isInit=FALSE THEN							

	modtcpslaveinit(en_in:=TRUE,					//Modbus TCP Slave初始化功能块使能
	xenable:=TRUE,									//使能初始化功能
	iport:=502,										//开放端口号502
	en_out=>eout,									//Modbus TCP Slave初始化功能块执行完成
	isocket=>iSocket,								//创建的socket存入变量
	uierror=>uiErr);								//Modbus TCP Slave初始化功能块执行错误信息

	IF isocket>=0 AND uiErr=0 THEN					//成功创建socket且无错误，逻辑标志置位，下周期执行ELSE
		isInit:=TRUE;	

		enCtr:=FALSE;
		ELSE                                        //等待连接成功
		modtcpslaveinit(en_in:=0,xenable:=0);	
	END_IF


ELSE

// =============================================================================
// 段 B: 从站周期服务 — 映射 HR/IR 缓冲区，看门狗 2000ms
// =============================================================================
	modtcpslavectrl(en_in:=enCtr,					//Modbus TCP Slave执行功能块使能
	xenable:=TRUE,									//Modbus TCP Slave执行功能使能
	isocket:=isocket,								//输入创建的socket
	dwatchdogtime:=2000,							//看门狗时间
	p_clientsocket:=ADR(arClient),					//将连接进来的socket存放到数组
	imaxclientcount:=10,							//设置最大连接数量
	uido_number:=10,uido_startaddr:=0,pdo_data:=ADR(ardo_data),		//uido_number设定线圈个数，uido_startaddr设定线圈起始地址，数据存放在ardo_data数组
	uidi_number:=10,uidi_startaddr:=0,pdi_data:=ADR(ardi_data),		//uidi_number设定离散型数据个数，uidi_startaddr设定离散型数据起始地址，数据存放在ardi_data数组
	uireg_number:=655,uireg_startaddr:=0,preg_data:=ADR(modbusData), //uireg_number设定保持型寄存器个数，uireg_startaddr设定保持型寄存器起始地址，数据存放在arreg_data数组
	uiai_number:=79,uiai_startaddr:=0,pai_data:=ADR(modbusInputRegs),//uiai_number设定输入型寄存器个数，uiai_startaddr设定输入型寄存器起始地址，数据存放在arai_data数组
	en_out=>eout,									//Modbus TCP Slave执行功能块执行完成
	uierror=>uierr);								//Modbus TCP Slave执行功能块执行错误信息
	enctr:=TRUE;
	IF uierr <>0 THEN                               //如果从站报错，则重新连接从站
		modtcpslaveinit(en_in:=0,xenable:=0);	
		isInit:=0;
	END_IF
	//iMode:  0 下电  1 上电  2 速度模式  3 停止  4 位置模式  5 继续运行
	//方位轴指令
(*
	Az_ctrl.iMode:=WORD_TO_INT(modbusData[0]);
	AZ_ctrl.rTarVel:=WORD_TO_REAL(modbusData[1]);
	AZ_ctrl.rTarPos:=WORD_TO_REAL(modbusData[2])*-1.0;

	//俯仰轴指令
	El_ctrl.iMode:=WORD_TO_INT(modbusData[10]);
	El_ctrl.rTarVel:=WORD_TO_REAL(modbusData[11]);
	El_ctrl.rTarPos:=WORD_TO_REAL(modbusData[12])+90.0;
	*)

	// =============================================================================
	// 段 C: 解析 HR 下发（保持寄存器 modbusData → 内部变量）
	// HR[0..3] UTC  HR[7] 控制字  HR[8..18]Az  HR[19..29]El  HR[30..39]Ti
	// HR[43] AGC门限  HR[45..48]轨道时间  HR[51..54]拉偏  HR[57..58]俯仰零位
	// =============================================================================
	UTC_Union.Apart_word[1]:=modbusData[3];
	UTC_Union.Apart_word[2]:=modbusData[2];
	UTC_Union.Apart_word[3]:=modbusData[1];
	UTC_Union.Apart_word[4]:=modbusData[0];
	UTC_New:=UTC_Union.Apart_ulint;
	DeltaTimeBetPC := UTC_New - TO_ULINT(GVL.dRealTime);
	// HR[7] 控制字位定义（WORD_AS_BIT）
	CtrlBool(W:=modbusData[7],
			B14=>bCommReset,
			B13=>Axis2Remote.bPIDEnable,
			B12=>Axis1Remote.bPIDEnable,
			B11=>Axis3Remote.bPIDEnable,
			B10=>bStartTrackAcu,
			B07=>bIFPoly,
			B06=>bSearch, //十字搜索开启标识
			);
	//方位轴指令
	iMode_2:=WORD_TO_INT(modbusData[8]);
	Pos2_Union.Apart_word[2]:=modbusData[9];
	Pos2_Union.Apart_word[1]:=modbusData[10];
	rPosCmd_2:=DINT_TO_LREAL( DWORD_TO_DINT( Pos2_Union.Apart_dword[1]))/100000*-1;
	rVelcmd_2:=DINT_TO_LREAL( WORD_TO_INT(modbusData[11]))/1000*-1;
	rP_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[12]))/1000;
	rI_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[13]))/1000;
	rD_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[14]))/1000;
	rThreshold_2:=WORD_TO_INT(modbusData[15])/1000;
	rAcceleration_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[16]))/1000;
	rDeceleration_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[17]))/1000;
	rVelLim_2:=INT_TO_LREAL(WORD_TO_INT(modbusData[18]))/1000;

	//俯仰轴指令
	iMode_1:=WORD_TO_INT(modbusData[19]);
	Pos1_Union.Apart_word[2]:=modbusData[20];
	Pos1_Union.Apart_word[1]:=modbusData[21];
	rPosCmd_1:=DINT_TO_LREAL( DWORD_TO_DINT( Pos1_Union.Apart_dword[1]))/100000+90;
	rVelcmd_1:=DINT_TO_LREAL( WORD_TO_INT(modbusData[22]))/1000;
	rP_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[23]))/1000;
	rI_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[24]))/1000;
	rD_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[25]))/1000;
	rThreshold_1:=WORD_TO_INT(modbusData[26])/1000;
	rAcceleration_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[27]))/1000;
	rDeceleration_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[28]))/1000;
	rVelLim_1:=INT_TO_LREAL(WORD_TO_INT(modbusData[29]))/1000;

	//倾斜轴指令
	iMode_3:=WORD_TO_INT(modbusData[30]);
	Pos3_Union.Apart_word[2]:=modbusData[31];
	Pos3_Union.Apart_word[1]:=modbusData[32];
	rPosCmd_3:=DINT_TO_LREAL( DWORD_TO_DINT( Pos3_Union.Apart_dword[1]))/100000*-1;
	rVelcmd_3:=DINT_TO_LREAL( WORD_TO_INT(modbusData[33]))/1000*-1;
	rP_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[34]))/1000;
	rI_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[35]))/1000;
	rD_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[36]))/1000;
	rThreshold_3:=WORD_TO_INT(modbusData[37])/1000;
	rAcceleration_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[38]))/1000;
	rDeceleration_3:=INT_TO_LREAL(WORD_TO_INT(modbusData[39]))/1000;


	//AGC锁定门限
	AGC_Value:=(WORD_TO_UDINT(modbusData[43])/100.0);
	GVL.Chanthreshold:=AGC_Value;

	//轨道时间
	UTC_Orbit_Union.Apart_word[1]:=modbusData[48];
	UTC_Orbit_Union.Apart_word[2]:=modbusData[47];
	UTC_Orbit_Union.Apart_word[3]:=modbusData[46];
	UTC_Orbit_Union.Apart_word[4]:=modbusData[45];
	UTC_Orbit_New:=UTC_Orbit_Union.Apart_ulint;
	//时间拉偏
	TimeBias_Union.Apart_word[1]:=modbusData[50];
	TimeBias_Union.Apart_word[2]:=modbusData[49];
	rTimeBias:=DINT_TO_LREAL( DWORD_TO_DINT( TimeBias_Union.Apart_dword[1]))/100000.0; //单位为秒
	IF rTimeBias>0.4 THEN//时间偏置最大限制 正负0.4秒
		rTimeBias:=0.4;
	ELSIF rTimeBias<-0.4 THEN
		rTimeBias:=-0.4;
	END_IF
	rTimeBias:=rTimeBias*1000000000;//秒转纳秒
	//两轴拉偏
	Bias2_Union.Apart_word[1]:=modbusData[52];
	Bias2_Union.Apart_word[2]:=modbusData[51];
	rBias_2:=DINT_TO_LREAL( DWORD_TO_DINT( Bias2_Union.Apart_dword[1]))/100000.0*(-1);

	Bias1_Union.Apart_word[1]:=modbusData[54];
	Bias1_Union.Apart_word[2]:=modbusData[53];
	rBias_1:=DINT_TO_LREAL( DWORD_TO_DINT( Bias1_Union.Apart_dword[1]))/100000.0;

	//俯仰零值
	AcuElOffset.Apart_word[1]:=modbusData[58];
	AcuElOffset.Apart_word[2]:=modbusData[57];
	lrElOffset:=DINT_TO_LREAL( DWORD_TO_DINT( AcuElOffset.Apart_dword[1]))/100000.0;
	// ----- 程引轨道表: UTC_Orbit_New 递增时移位写入 aUTC_TIME / aPosCmd_x -----

	// 指向模式最大速度 HR[61..63] → GVL.AxisXRemote.Pos_Vel
	rAzPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[61]))/1000.0;
	rElPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[62]))/1000.0;
	rTlPosVel:=INT_TO_LREAL(WORD_TO_INT(modbusData[63]))/1000.0;

	IF rAzPosVel <= 16.0 THEN
		GVL.Axis2Remote.Pos_Vel := rAzPosVel;
	ELSE
		GVL.Axis2Remote.Pos_Vel := 16;
	END_IF

	IF rElPosVel <= 11.0 THEN
		GVL.Axis1Remote.Pos_Vel := rElPosVel;
	ELSE
		GVL.Axis1Remote.Pos_Vel := 11;
	END_IF

	IF rTlPosVel <= 8.0 THEN
		GVL.Axis3Remote.Pos_Vel := rTlPosVel;
	ELSE
		GVL.Axis3Remote.Pos_Vel := 8;
	END_IF

	FOR iCheck:=1 TO 10 DO
		IF UTC_Orbit_New>aUTC_TIME[iCheck] THEN
			bPass:=TRUE;
		ELSE
			bPass:=FALSE;
			EXIT;
		END_IF
	END_FOR
	IF bPass THEN //命令刷新，则更新序列
		FOR isave:=1 TO 9 DO
			aUTC_TIME[isave]:=aUTC_TIME[isave+1];
			aPosCmd_1[isave]:=aPosCmd_1[isave+1];
			aPosCmd_2[isave]:=aPosCmd_2[isave+1];
		END_FOR
		aUTC_TIME[10]:=UTC_Orbit_New;
		aPosCmd_1[10]:=rPosCmd_1;
		aPosCmd_2[10]:=rPosCmd_2;
	END_IF
	//若不是程引模式，则清空轨道时间数据
	IF Axis1Remote.iMode<>4 AND Axis2Remote.iMode<>4 THEN
		FOR iCheck:=1 TO 10 DO
			aUTC_TIME[iCheck]:=0;;
		END_FOR
	END_IF

	// =============================================================================
	// 段 D: 打包 IR 上报（modbusInputRegs，上位机只读）
	// IR[0..3]时间 IR[5]Error IR[6..9]DI/DO IR[10+]三轴状态 IR[59..65]跟踪机
	// IR[69..74]跟踪偏差 IR[75..78]理论角
	// =============================================================================
	IF icount<16#FFFF THEN
		icount:=icount+1;
	ELSE
		icount:=0;
	END_IF

	DI1_Union(B15:=SecurityCheck.bPrelimit_Positive_1,						//俯仰轴预限位--正 B15=0为未触发，B15=1为触发
			B14:=SecurityCheck.bFinallimit_1,								//俯仰轴终限位
			B13:=SecurityCheck.bPrelimit_Negative_1,						//俯仰轴预限位--负
			B12:=SecurityCheck.bFinallimit_1,								//俯仰位终限位
			B11:=SecurityCheck.bPrelimit_Positive_2,						//方位轴预限位--正
			B10:=SecurityCheck.bFinallimit_2,								//方位轴终限位
			B09:=SecurityCheck.bPrelimit_Negative_2,						//方位轴预限位--负
			B08:=SecurityCheck.bFinallimit_2,								//方位轴终限位
			B07:=FALSE,												//倾斜预限位--正
			B06:=FALSE,												//倾斜终限位--正
			B05:=FALSE,												//倾斜预限位--负
			B04:=FALSE,												//倾斜终限位--负
			B03:=FALSE,												//方位轴过零检测
			B02:=Axis2Status.bBrake,								//方位轴抱闸状态 0为解抱闸，1为抱闸
			B01:=Axis1Status.bBrake,								//俯仰轴抱闸状态
			B00:=Axis3Status.bBrake,								//倾斜轴抱闸状态
			W=>DI1_word	);

	DI2_Union(B15:=FALSE,								//
			B14:=FALSE,								//
			B13:=FALSE,
			B12:=FALSE,
			B11:=FALSE,
			B10:=FALSE,
			B09:=FALSE,
			B08:=FALSE,
			B07:=FALSE,
			B06:=FALSE,
			B05:=GVL.bError_Reset,											//错误复位符
			B04:=GVL.bLocalCtrl,											//本远控标识符
			B03:=FALSE,									//退限位标识符
			B02:=Axis2Remote.bPIDEnable,											//方位轴PID使能状态
			B01:=Axis1Remote.bPIDEnable,											//俯仰轴PID使能状态
			B00:=Axis3Remote.bPIDEnable,											//倾斜轴PID使能状态
			W=>DI2_word);
	DO1_Union(B15:=FALSE,								//中心体急停指示灯
			B14:=FALSE,							//声光报警		1为触发，0为未触发
			B13:=FALSE,							//爬梯急停指示灯 B13=1为亮 B13=0为灭
			B12:=FALSE,							//机柜蜂鸣器	B12=1为触发，B12=0为未触发
			B11:=FALSE,							//限位释放指示灯 同上 
			B10:=FALSE,						//本远控指示灯	B10=1为本控，B10=0为远控
			B09:=FALSE,							//系统状态指示灯 B09=1为异常，B09=0为正常	
			B08:=Axis2Status.bBrake,								//方位轴抱闸输出 B08=1为抱闸输出 B08=1为解抱闸输出
			B07:=Axis1Status.bBrake,								//俯仰轴抱闸输出 同上
			B06:=Axis3Status.bBrake,								//倾斜轴抱闸输出 同上
			B05:=FALSE,										//方位风扇输出	B05=1为风扇运行，B05=0为风扇未运行
			B04:=FALSE,										//俯仰风扇输出	同上
			B03:=FALSE,										//倾斜风扇输出	同上
			B02:=Axis2Status.bServo_Enable,									//方位轴供电
			B01:=Axis1Status.bServo_Enable,									//俯仰轴供电
			B00:=Axis3Status.bServo_Enable,									//倾斜轴供电
			W=>DO1_word);
	DO2_Union(B15:=Axis2Status.bServo_Enable,//NOT(Axis1Status.Disabled),						//方位主电机使能状态
			B14:=Axis2Status.bServo_Enable,//NOT(Axis1Status.Disabled),							//方位从电机使能状态
			B13:=Axis1Status.bServo_Enable,//NOT(Axis2Status.Disabled),							//俯仰主电机使能状态		
			B12:=Axis1Status.bServo_Enable,//NOT(Axis2Status.Disabled),							//俯仰从电机使能状态
			B11:=Axis3Status.bServo_Enable,		//倾斜主电机使能状态
	 		B10:=Axis3Status.bServo_Enable,		//倾斜从电机使能状态
			B09:=Az_ctrl_1.bStop_2,			//方位轴主电机停止标识符
	 		B08:=Az_ctrl_1.bStop_2,					  //方位轴从电机停止标识符
	 		B07:=El_ctrl_1.bStop_1,		    //俯仰轴主电机停止标识符
			B06:=El_ctrl_1.bStop_1,				//俯仰轴从电机停止标识符
	 		B05:=Ti_ctrl_1.bStop_3,							//倾斜轴主电机停止标识符
			B04:=Ti_ctrl_1.bStop_3,							//倾斜轴从电机停止标识符
	 		B03:=0,
	 		B02:=0,
			B01:=0,
			B00:=0,
			W=>DO2_word	);

	//命令角与实际角偏差
	IF bLocalCtrl THEN
		IF  Axis1Local.iMode=4 THEN
			BiasSub1_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis1Local.rPosCmd-rFctPosReal_1)*100000.0));//读取位置
		ELSE
			BiasSub1_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	ELSE
		IF Axis1Remote.iMode=2  THEN 
			BiasSub1_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis1Remote.rPosCmd-rFctPosReal_1)*100000.0));//读取位置
		ELSIF Axis1Remote.iMode=4 THEN
			BiasSub1_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((RealTimePosCal.rInterElPos-rFctPosReal_1)*100000.0));//读取位置
		ELSE
			BiasSub1_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	END_IF

	IF bLocalCtrl THEN
		IF Axis2Local.iMode=4 THEN
			BiasSub2_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis2Local.rPosCmd-rFctPosReal_2)*100000.0));//读取位置
		ELSE
			BiasSub2_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	ELSE
		IF Axis2Remote.iMode=2 THEN
			BiasSub2_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis2Remote.rPosCmd-rFctPosReal_2)*100000.0));//读取位置
		ELSIF Axis2Remote.iMode=4 THEN
			BiasSub2_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((rFctPosReal_2-RealTimePosCal.rInterAzPos)*100000.0));//读取位置
		ELSE
			BiasSub2_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	END_IF

	IF bLocalCtrl THEN
		IF Axis3Local.iMode=4 THEN
			BiasSub3_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis3Local.rPosCmd-rFctPosReal_3)*100000.0));//读取位置
		ELSE
			BiasSub3_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	ELSE
		IF Axis3Remote.iMode=2 THEN
			BiasSub3_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis3Remote.rPosCmd-rFctPosReal_3)*100000.0));//读取位置
		ELSIF Axis2Remote.iMode=4 THEN
			BiasSub3_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((Axis3Remote.rPIDCmdPos-rFctPosReal_3)*100000.0));//读取位置
		ELSE
			BiasSub3_Union.Apart_dword[1]:=0;//读取位置
		END_IF
	END_IF

	// uPTPTime_Union.Apart_ulint:=TO_ULINT(GVL.dPTPCSTTime/1000000);
	uPTPTime_Union.Apart_ulint:=TO_ULINT((GVL.dRealTime - 8 * 3600 * 1000) * 1000000);
	modbusInputRegs[0]:=uPTPTime_Union.Apart_word[4];
	modbusInputRegs[1]:=uPTPTime_Union.Apart_word[3];
	modbusInputRegs[2]:=uPTPTime_Union.Apart_word[2];
	modbusInputRegs[3]:=uPTPTime_Union.Apart_word[1];
	modbusInputRegs[4]:=INT_TO_WORD( icount);
	modbusInputRegs[5]:=INT_TO_WORD(Error_code);//错误代码
	modbusInputRegs[6]:=DI1_word;
	modbusInputRegs[7]:=DI2_word;
	modbusInputRegs[8]:=DO1_word;
	modbusInputRegs[9]:=DO2_word;


	PosSub1_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((rFctPosReal_1-90)*100000.0));//读取俯仰位置

	PosSub2_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((rFctPosReal_2*-1)*100000.0));//读取方位位置

	PosSub3_Union.Apart_dword[1]:=DINT_TO_DWORD( REAL_TO_DINT((rFctPosReal_3*-1)*100000.0));//读取倾斜位置


	//方位轴状态
	modbusInputRegs[10]:=INT_TO_WORD(Axis2Remote.iMode);

	modbusInputRegs[13]:=PosSub2_Union.Apart_word[2];
	modbusInputRegs[14]:=PosSub2_Union.Apart_word[1];

	modbusInputRegs[17]:=INT_TO_WORD(REAL_TO_INT(rFctVelReal_2*1000.0));							//速度

	modbusInputRegs[19]:=REAL_TO_UINT(Axis2Remote.rP*1000);
	modbusInputRegs[20]:=REAL_TO_UINT(Axis2Remote.rI*1000);
	modbusInputRegs[21]:=REAL_TO_UINT(Axis2Remote.rD*1000);
	modbusInputRegs[22]:=REAL_TO_UINT(Axis2Remote.rPIDThre*1000);
	modbusInputRegs[23]:=INT_TO_WORD(REAL_TO_INT(securitycheck.rAzCurrent*100.0));


	//俯仰轴状态
	modbusInputRegs[27]:=INT_TO_WORD(Axis1Remote.iMode);

	modbusInputRegs[30]:=PosSub1_Union.Apart_word[2];
	modbusInputRegs[31]:=PosSub1_Union.Apart_word[1];

	modbusInputRegs[34]:=INT_TO_WORD(REAL_TO_INT(rFctVelReal_1*1000));							     //速度

	modbusInputRegs[36]:=REAL_TO_UINT(Axis1Remote.rP*1000);
	modbusInputRegs[37]:=REAL_TO_UINT(Axis1Remote.rI*1000);
	modbusInputRegs[38]:=REAL_TO_UINT(Axis1Remote.rD*1000);
	modbusInputRegs[39]:=REAL_TO_UINT(Axis1Remote.rPIDThre*1000);
	modbusInputRegs[40]:=INT_TO_WORD(REAL_TO_INT(securitycheck.rElCurrent*100.0));
	//倾斜轴状态
	modbusInputRegs[44]:=INT_TO_WORD(Axis3Remote.iMode);

	modbusInputRegs[47]:=PosSub3_Union.Apart_word[2];
	modbusInputRegs[48]:=PosSub3_Union.Apart_word[1];

	modbusInputRegs[51]:=INT_TO_WORD(REAL_TO_INT(rFctVelReal_3*1000.0));							//速度

	modbusInputRegs[53]:=REAL_TO_UINT(Axis3Remote.rP*1000);
	modbusInputRegs[54]:=REAL_TO_UINT(Axis3Remote.rI*1000);
	modbusInputRegs[55]:=REAL_TO_UINT(Axis3Remote.rD*1000);
	modbusInputRegs[56]:=REAL_TO_UINT(Axis3Remote.rPIDThre*1000);
	modbusInputRegs[57]:=INT_TO_WORD(REAL_TO_INT(securitycheck.rTlCurrent*100.0));
	//跟踪接收机预留

	modbusInputRegs[69]:=BiasSub2_Union.Apart_word[2];
	modbusInputRegs[70]:=BiasSub2_Union.Apart_word[1];
	modbusInputRegs[71]:=BiasSub1_Union.Apart_word[2];
	modbusInputRegs[72]:=BiasSub1_Union.Apart_word[1];
	modbusInputRegs[73]:=BiasSub3_Union.Apart_word[2];
	modbusInputRegs[74]:=BiasSub3_Union.Apart_word[1];
	//上报用于校相的方位俯仰轴理论值 （插值位置加当前拉偏位置）
	rAzTheory:=RealTimePosCal.rInterAzPos*(-1);
	rAzTheory_Union.Apart_dword[1]:=DINT_TO_DWORD(LREAL_TO_DINT(rAzTheory*100000.0));
	rEltheory:=RealTimePosCal.rInterElPos-90;
	rEltheory_Union.Apart_dword[1]:=DINT_TO_DWORD(LREAL_TO_DINT(rEltheory*100000.0));
	modbusInputRegs[75]:=rAzTheory_Union.Apart_word[2];
	modbusInputRegs[76]:=rAzTheory_Union.Apart_word[1];
	modbusInputRegs[77]:=rEltheory_Union.Apart_word[2];
	modbusInputRegs[78]:=rEltheory_Union.Apart_word[1];

	//跟踪接收机状态字上报
	Chan_Union(B15:=GVL.Chan1Lock,
			  B14:=GVL.Chan1Online,
			  B13:=GVL.Chan2Lock,
			  B12:=GVL.Chan2Online,
			  //B11:=GVL.bStartTrack,
			  B11:=Read_485.bEBN0Lock,
			  B10:=0,
			  B09:=0,
			  B08:=0,
			  B07:=0,
			  B06:=0,
			  B05:=0,
			  B04:=0,
			  B03:=0,
			  B02:=0,
			  B01:=0,
			  B00:=0,
			  w=>Chan_word);
			  (*
	IF GVL.Chan1AGC >= GVL.Chanthreshold THEN
		GVL.Chan1Lock:=TRUE;
	ELSE
		GVL.Chan1Lock:=FALSE;	
	END_IF
	*)
	//跟踪接收机数据上报
	// IF Ether_Cat.EL6022State=8 THEN
	IF TRUE THEN
			modbusInputRegs[59]:=Chan_word;
			modbusInputRegs[60]:=REAL_TO_WORD(GVL.Chan1AGC*1000);

	   IF GVL.Chan1Ua>0 THEN
			modbusInputRegs[61]:=REAL_TO_WORD(GVL.Chan1Ua*1000);
	   ELSE
			modbusInputRegs[61]:=(-1)*REAL_TO_WORD(65536-GVL.Chan1Ua*1000);	

	   END_IF

	   IF GVL.Chan1Ue>0 THEN
			modbusInputRegs[62]:=REAL_TO_WORD(GVL.Chan1Ue*1000);
	   ELSE
			modbusInputRegs[62]:=(-1)*REAL_TO_WORD(65536-GVL.Chan1Ue*1000);	

	   END_IF

			modbusInputRegs[63]:=REAL_TO_WORD(GVL.Chan2AGC*1000);
			modbusInputRegs[64]:=REAL_TO_WORD(GVL.Chan2Ua*1000);
			modbusInputRegs[65]:=REAL_TO_WORD(GVL.Chan2Ue*1000);
	ELSE
			modbusInputRegs[59]:=0;
			modbusInputRegs[60]:=0;
			modbusInputRegs[61]:=0;
			modbusInputRegs[62]:=0;
			modbusInputRegs[63]:=0;
			modbusInputRegs[64]:=0;
			modbusInputRegs[65]:=0;
	END_IF
	// =============================================================================
	// 段 E: 多项式程引系数 HR 解析（UnionLREAL_WORD，当前 RealTimePosCal 中已注释不用）
	// HR[71+] 各段 LREAL 系数，HR[335+] 节点时间；供 Get_AZ 备用路径
	// =============================================================================
	//IF GVL.AzCtrl.iMode = 11 AND GVL.ElCtrl.iMode = 11 THEN
	iCountPolyGet:=iCountPolyGet+1;
	//IF iCountPolyGet=10 THEN
		iCountPolyGet:=0;
	IF TRUE THEN
		FOR i := 0 TO 10 DO
			unionFun1_az[i].words[1] := modbusdata[74 + 4 * i];
			unionFun1_az[i].words[2] := modbusdata[73 + 4 * i];
			unionFun1_az[i].words[3] := modbusdata[72 + 4 * i];
			unionFun1_az[i].words[4] := modbusdata[71 + 4 * i];
			lrFun1_az[i] := unionFun1_az[i].lrealValue;

			unionFun2_az[i].words[1] := modbusdata[118 + 4 * i];
			unionFun2_az[i].words[2] := modbusdata[117 + 4 * i];
			unionFun2_az[i].words[3] := modbusdata[116 + 4 * i];
			unionFun2_az[i].words[4] := modbusdata[115 + 4 * i];
			lrFun2_az[i] := unionFun2_az[i].lrealValue;

			unionFun3_az[i].words[1] := modbusdata[162 + 4 * i];
			unionFun3_az[i].words[2] := modbusdata[161 + 4 * i];
			unionFun3_az[i].words[3] := modbusdata[160 + 4 * i];
			unionFun3_az[i].words[4] := modbusdata[159 + 4 * i];
			lrFun3_az[i] := unionFun3_az[i].lrealValue;

			unionFun4_az[i].words[1] := modbusdata[206 + 4 * i];
			unionFun4_az[i].words[2] := modbusdata[205 + 4 * i];
			unionFun4_az[i].words[3] := modbusdata[204 + 4 * i];
			unionFun4_az[i].words[4] := modbusdata[203 + 4 * i];
			lrFun4_az[i] := unionFun4_az[i].lrealValue;

			unionFun5_az[i].words[1] := modbusdata[250 + 4 * i];
			unionFun5_az[i].words[2] := modbusdata[249 + 4 * i];
			unionFun5_az[i].words[3] := modbusdata[248 + 4 * i];
			unionFun5_az[i].words[4] := modbusdata[247 + 4 * i];
			lrFun5_az[i] := unionFun5_az[i].lrealValue;

			unionFun6_az[i].words[1] := modbusdata[294 + 4 * i];
			unionFun6_az[i].words[2] := modbusdata[293 + 4 * i];
			unionFun6_az[i].words[3] := modbusdata[292 + 4 * i];
			unionFun6_az[i].words[4] := modbusdata[291 + 4 * i];
			lrFun6_az[i] := unionFun6_az[i].lrealValue;

			unionFun3_el[i].words[1] := modbusdata[450 + 4 * i];
			unionFun3_el[i].words[2] := modbusdata[449 + 4 * i];
			unionFun3_el[i].words[3] := modbusdata[448 + 4 * i];
			unionFun3_el[i].words[4] := modbusdata[447 + 4 * i];
			lrFun3_el[i] := unionFun3_el[i].lrealValue;

			unionFun4_el[i].words[1] := modbusdata[494 + 4 * i];
			unionFun4_el[i].words[2] := modbusdata[493 + 4 * i];
			unionFun4_el[i].words[3] := modbusdata[492 + 4 * i];
			unionFun4_el[i].words[4] := modbusdata[491 + 4 * i];
			lrFun4_el[i] := unionFun4_el[i].lrealValue;

			unionFun1_el[i].words[1] := modbusdata[362 + 4 * i];
			unionFun1_el[i].words[2] := modbusdata[361 + 4 * i];
			unionFun1_el[i].words[3] := modbusdata[360 + 4 * i];
			unionFun1_el[i].words[4] := modbusdata[359 + 4 * i];
			lrFun1_el[i] := unionFun1_el[i].lrealValue;

			unionFun2_el[i].words[1] := modbusdata[406 + 4 * i];
			unionFun2_el[i].words[2] := modbusdata[405 + 4 * i];
			unionFun2_el[i].words[3] := modbusdata[404 + 4 * i];
			unionFun2_el[i].words[4] := modbusdata[403 + 4 * i];
			lrFun2_el[i] := unionFun2_el[i].lrealValue;

			unionFun5_el[i].words[1] := modbusdata[538 + 4 * i];
			unionFun5_el[i].words[2] := modbusdata[537 + 4 * i];
			unionFun5_el[i].words[3] := modbusdata[536 + 4 * i];
			unionFun5_el[i].words[4] := modbusdata[535 + 4 * i];
			lrFun5_el[i] := unionFun5_el[i].lrealValue;

			unionFun6_el[i].words[1] := modbusdata[582 + 4 * i];
			unionFun6_el[i].words[2] := modbusdata[581 + 4 * i];
			unionFun6_el[i].words[3] := modbusdata[580 + 4 * i];
			unionFun6_el[i].words[4] := modbusdata[579 + 4 * i];
			lrFun6_el[i] := unionFun6_el[i].lrealValue;
		END_FOR
		i:=0;
		unionNodeTime1_az.words[1] := modbusdata[338];
		unionNodeTime1_az.words[2] := modbusdata[337];
		unionNodeTime1_az.words[3] := modbusdata[336];
		unionNodeTime1_az.words[4] := modbusdata[335];
		rNodeTime1_az := unionNodeTime1_az.lrealValue;

		unionNodeTime2_az.words[1] := modbusdata[342];
		unionNodeTime2_az.words[2] := modbusdata[341];
		unionNodeTime2_az.words[3] := modbusdata[340];
		unionNodeTime2_az.words[4] := modbusdata[339];
		rNodeTime2_az := unionNodeTime2_az.lrealValue;

		unionNodeTime3_az.words[1] := modbusdata[346];
		unionNodeTime3_az.words[2] := modbusdata[345];
		unionNodeTime3_az.words[3] := modbusdata[344];
		unionNodeTime3_az.words[4] := modbusdata[343];
		rNodeTime3_az := unionNodeTime3_az.lrealValue;

		unionNodeTime4_az.words[1] := modbusdata[350];
		unionNodeTime4_az.words[2] := modbusdata[349];
		unionNodeTime4_az.words[3] := modbusdata[348];
		unionNodeTime4_az.words[4] := modbusdata[347];
		rNodeTime4_az := unionNodeTime4_az.lrealValue;

		unionNodeTime5_az.words[1] := modbusdata[354];
		unionNodeTime5_az.words[2] := modbusdata[353];
		unionNodeTime5_az.words[3] := modbusdata[352];
		unionNodeTime5_az.words[4] := modbusdata[351];
		rNodeTime5_az := unionNodeTime5_az.lrealValue;

		unionStartTime.words[1]:=modbusdata[646];
		unionStartTime.words[2]:=modbusdata[645];
		unionStartTime.words[3]:=modbusdata[644];
		unionStartTime.words[4]:=modbusdata[643];
		starttime:=unionStartTime.lrealValue;
		unionEndTime.words[1] := modbusdata[358];
		unionEndTime.words[2] := modbusdata[357];
		unionEndTime.words[3] := modbusdata[356];
		unionEndTime.words[4] := modbusdata[355];
		rEndTime := unionEndTime.lrealValue;

		//FOR i := 0 TO 5 DO

		//END_FOR

		unionNodeTime1_el.words[1] := modbusdata[626];
		unionNodeTime1_el.words[2] := modbusdata[625];
		unionNodeTime1_el.words[3] := modbusdata[624];
		unionNodeTime1_el.words[4] := modbusdata[623];
		rNodeTime1_el := unionNodeTime1_el.lrealValue;

		unionNodeTime2_el.words[1] := modbusdata[630];
		unionNodeTime2_el.words[2] := modbusdata[629];
		unionNodeTime2_el.words[3] := modbusdata[628];
		unionNodeTime2_el.words[4] := modbusdata[627];
		rNodeTime2_el := unionNodeTime2_el.lrealValue;

		unionNodeTime3_el.words[1] := modbusdata[634];
		unionNodeTime3_el.words[2] := modbusdata[633];
		unionNodeTime3_el.words[3] := modbusdata[632];
		unionNodeTime3_el.words[4] := modbusdata[631];
		rNodeTime3_el := unionNodeTime3_el.lrealValue;

		unionNodeTime4_el.words[1] := modbusdata[638];
		unionNodeTime4_el.words[2] := modbusdata[637];
		unionNodeTime4_el.words[3] := modbusdata[636];
		unionNodeTime4_el.words[4] := modbusdata[635];
		rNodeTime4_el := unionNodeTime4_el.lrealValue;

		unionNodeTime5_el.words[1] := modbusdata[642];
		unionNodeTime5_el.words[2] := modbusdata[641];
		unionNodeTime5_el.words[3] := modbusdata[640];
		unionNodeTime5_el.words[4] := modbusdata[639];
		rNodeTime5_el := unionNodeTime5_el.lrealValue;

		(*
		//验证上位机下发数据
		unionSum.words[1]:=modbusdata[650];
		unionSum.words[2]:=modbusdata[649];
		unionSum.words[3]:=modbusdata[648];
		unionSum.words[4]:=modbusdata[647];
		lrSum:=unionSum.lrealValue;

		lrSumlocal:=lrFun1_az[10]+lrFun2_az[10]+lrFun3_az[10]+lrFun4_az[10]+lrFun5_az[10]+lrFun6_az[10]
					+lrFun1_el[10]+lrFun2_el[10]+lrFun3_el[10]+lrFun4_el[10]+lrFun5_el[10]+lrFun6_el[10];
		*)

		IF NOT bNotFirst THEN
			bCheck := TRUE; // 接收系数完成 开始检测 检测一次
		END_IF
		bNotFirst := TRUE;
	ELSE // 多项式相关变量清零
		bCheck := FALSE;
		bNotFirst := FALSE;
		rNodeTime1_az := 0.0;
		rNodeTime2_az := 0.0;
		rNodeTime3_az := 0.0;
		rNodeTime4_az := 0.0;
		rNodeTime5_az := 0.0;
		rEndTime := 0.0;

		FOR i := 0 TO 10 DO
			lrFun1_az[i] := 0;
			lrFun2_az[i] := 0;
			lrFun3_az[i] := 0;
			lrFun4_az[i] := 0;
			lrFun5_az[i] := 0;
			lrFun6_az[i] := 0;
			lrFun3_el[i] := 0;
			lrFun4_el[i] := 0;
		END_FOR

		rNodeTime1_el := 0;
		rNodeTime2_el := 0;
		rNodeTime3_el := 0;
		rNodeTime4_el := 0;
		rNodeTime5_el := 0;

		FOR i := 0 TO 5 DO
			lrFun1_el[i] := 0;
			lrFun2_el[i] := 0;
			lrFun5_el[i] := 0;
			lrFun6_el[i] := 0;
		END_FOR
	END_IF

END_IF

(*==============================================================================
  PRG: Az_ctrl_1（方位轴 Az 顶层程序）
  任务: Canopen 10ms
  作用: 与 El_ctrl_1 对称，负责方位轴反馈、状态、自跟踪、AGC 搜索及 Az_Ctrl_FB 调用
  特点:
    - 软限位 ±275°；程引目标 rInterAzPos
    - 自跟踪用 AutoTrackingCal.rChanUa（方位误差，符号与俯仰相反）
    - 含螺旋/联合搜索触发: bstartSearchAz, bstartSearchEl（供俯仰 AGC 搜索联动）
    - rPIDCmdPos 中 SECURITYCHECK.AZ_out 为减号（与俯仰 el_out 加号不同）
==============================================================================*)


a := 2;  // 无业务含义，保持原逻辑
IF GVL.Error_code <> 0 THEN
	bVisError := TRUE;
ELSE
	bVisError := FALSE;
END_IF

(* 远控参量曾在此直赋，现由 Modbus_Slave 统一写入 Axis2Remote *)

// =============================================================================
// 段 1: 驱动状态 → Axis2Status
// =============================================================================
Axis2Status.Error := GVL.bAzStsBit3;
Axis2Status.ErrorID := GVL.eAzErrorcode;
Axis2Status.bServo_Enable := GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2;
Axis2Status.bBrake := NOT (GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2);
Axis2Status.Disabled := NOT (GVL.bAzStsBit0 AND GVL.bAzStsBit1 AND GVL.bAzStsBit2);
Axis2Remote.rSoft_limit_Negative:=-275;Axis2Remote.rSoft_limit_Postive:=275;
Axis2Local.rSoft_limit_Negative:=-275;Axis2Local.rSoft_limit_Postive:=275;

// =============================================================================
// 段 2: CANopen 反馈 → rFctVelReal_2 / rFctPosReal_2（方位无额外偏移）
// =============================================================================
rFctVelReal_2:=DINT_TO_REAL(diAzActVel)/524288.0*360.0;
rFctPosReal_2:=DINT_TO_REAL(diAzActPos)/524288.0*360.0;

// =============================================================================
// 段 3: rPosCmd 硬限位 ±275°
// =============================================================================
Axis2Limit_pos:=275;
Axis2Limit_Neg:=-275;
IF Axis2Remote.rPosCmd>Axis2Limit_pos THEN
	Axis2Remote.rPosCmd:=275;
ELSIF Axis2Remote.rPosCmd<Axis2Limit_Neg THEN
	 Axis2Remote.rPosCmd:=-275;  
END_IF

IF Axis2Local.rPosCmd>Axis2Limit_pos THEN
	Axis2Local.rPosCmd:=275;
ELSIF Axis2Local.rPosCmd<Axis2Limit_Neg THEN
	 Axis2Local.rPosCmd:=-275;  
END_IF

// =============================================================================
// 段 4: 停稳判定 → Axis2Status.Moving
// =============================================================================
IF  ABS(rFctVelReal_2)<0.035 THEN
	Stop2_Count:=Stop2_Count+1;
	IF Stop2_Count>100 THEN
		Stop2_Count:=101;
		bStop_2:=TRUE;;
	END_IF
ELSE
	Stop2_Count:=0;
	bStop_2:=FALSE;
END_IF
Axis2Status.Moving := NOT bStop_2;

// =============================================================================
// 段 5: PID 使能（mode 2 / 4）
// =============================================================================
IF Axis2Remote.iMode=2 OR Axis2Remote.iMode=4 THEN
	Axis2Remote.bPIDEnable:=TRUE;
ELSE
	Axis2Remote.bPIDEnable:=FALSE;
END_IF

// =============================================================================
// 段 6: 远控 ↔ 本控 切换保护（与 El 相同，halt=7 → 停稳 → powerOff=0）
// =============================================================================
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis2Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_2=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis2Local.iMode:=0;
		Axis2Remote.iMode:=0;
		IF Axis2Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis2Local.iMode:=7;
		Axis2Remote.iMode:=7;
	END_IF
END_IF

IF Axis2Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_2=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis2Local.iMode:=0;
		Axis2Remote.iMode:=0;
		IF Axis2Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis2Remote.iMode:=7;
		Axis2Local.iMode:=7;
	END_IF
END_IF

// =============================================================================
// 段 7: AGC 峰值搜索（bstart 来自 Modbus_slave.bSearch）
// mode2: rPosCmd；mode4: RealTimePosCal.rInterAzPos；需俯仰 El-90°>rElthreshold
// =============================================================================
IF Axis2Remote.iMode=2 THEN
			bstartagcmaxsearch:=Modbus_slave.bSearch;
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_tb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=Axis2Remote.rPosCmd,rcurrentpos:=GVL.rFctPosReal_2,
				rStepBiasNow:=0,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_tb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=Axis2Remote.rPosCmd,rcurrentpos:=GVL.rFctPosReal_2,
				rStepBiasNow:=0,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
		ELSIF Axis2Remote.iMode=4 AND (GVL.rFctPosReal_1 - 90)>rElthreshold  THEN
			bstartagcmaxsearch:=Modbus_slave.bSearch;
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
				rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
		ELSIF Axis2Remote.iMode =0  OR Axis2Remote.iMode =7 THEN
			bstartagcmaxsearch:=FALSE;
			iCountSearch:=0;
			agcmaxsearch_pb(bstart:=bstartagcmaxsearch,rAGCNow:=GVL.Chan1AGC,btrig:=bstartSearchAz,
			rinterPos:=RealTimeposcal.rInterAzPos,rcurrentpos:=GVL.rFctPosReal_2,
			rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
			rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
		END_IF

// =============================================================================
// 段 8: 自跟踪拉偏（远控）— 方位用 rChanUa，程引时符号与俯仰相反
// =============================================================================
IF GVL.bStartTrack AND Axis2Remote.iMode=4 THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	IF rAuToStepBias > rAutoTrackingBiasMax THEN
		rAuToStepBias := rAutoTrackingBiasMax;
	ELSIF rAuToStepBias < -rAutoTrackingBiasMax THEN
		rAuToStepBias := -rAutoTrackingBiasMax;
	ELSE
		rAuToStepBiasTemp:=(-0.04)*AutoTrackingCal.rDirSenFac*AutoTrackingCal.rChanUa;
		rAuToStepBias:=rAuToStepBias-AutoTrackingCal.rDirSenFac*rKAuToStepBias*AutoTrackingCal.rChanUa/1000.0;
	END_IF
ELSIF NOT GVL.bStartTrack AND Axis2Remote.iMode=4 THEN
	IF 	rAuToStepBias>0 THEN//关闭自跟踪后自跟踪拉偏量逐渐归0
		rAuToStepBias:=rAuToStepBias-rAutoStep;
	ELSIF rAuToStepBias<0 THEN
		rAuToStepBias:=rAuToStepBias+rAutoStep;
	ELSE
		rAuToStepBias:=0;
	END_IF

	IF Modbus_Slave.rBias_2>rStepBias THEN
		rStepBias:=rStepBias+rStep;
		IF rStepBias>=Modbus_Slave.rBias_2 THEN
			rStepBias:=Modbus_Slave.rBias_2;
		END_IF
	ELSIF Modbus_Slave.rBias_2<rStepBias THEN
		rStepBias:=rStepBias-rStep;
		IF rStepBias<=Modbus_Slave.rBias_2 THEN
			rStepBias:=Modbus_Slave.rBias_2;
		END_IF
	END_IF
	rAuToStepBiasTemp:=0;
ELSIF GVL.bStartTrack AND Axis2Remote.iMode=2 THEN
	Axis2Remote.bStartAutoTrack := TRUE;
	Axis2Remote.rChanU := -AutoTrackingCal.rChanUa;
ELSE
	Axis2Remote.bStartAutoTrack := FALSE;	
	rAuToStepBias:=0;
	rStepBias:=0;
	rAuToStepBiasTemp:=0;
END_IF

// 本控自跟踪
IF GVL.bStartLocalAutoTrack AND Axis2Local.iMode = 4 THEN
	Axis2Local.bStartAutoTrack := TRUE;
	Axis2Local.rChanU := -AutoTrackingCal.rChanUaLocal;
ELSE
	Axis2Local.bStartAutoTrack := FALSE;
END_IF

// =============================================================================
// 段 9: 合成 rPIDCmdPos（注意 AZ_out 为减）→ Az_Ctrl_FB
// =============================================================================
Axis2Remote.rPIDCmdPos:=RealTimePosCal.rInterAzPos+rStepBias+rAuToStepBias+rSearchNextStepTarget-SECURITYCHECK.AZ_out+rAuToStepBiasTemp;

IF Axis2Remote.rPIDCmdPos<-275 THEN
	Axis2Remote.rPIDCmdPos:=-275;
ELSIF Axis2Remote.rPIDCmdPos>275 THEN
	Axis2Remote.rPIDCmdPos:=275;
END_IF

Axis2_Ctrl(sLocal:=Axis2Local, sCtrl:=Axis2Remote, sStatus:=Axis2Status, sVisible:=Axis2Visible, rRealPos:=rFctPosReal_2, rPosLimK:=0.34);

(*==============================================================================
  FB: Az_Ctrl_FB（方位轴 Azimuth 控制功能块）
  与 El_Ctrl_FB 结构完全相同，差异点:
    - 操作的 GVL 变量为 Az 系列（diAzTargetVel / bAzCtrlBitX / eAzErrorcode 等）
    - positionMode 加速度为 12 deg/s²（El 为 9 deg/s²）
    - positionMode 的 Kp=0.6（El 为 0.7），本控 programBootMode Kp=0.6
    - programBootMode 参数来自 PersistentVars.rAzXxx

  速度换算公式（通用）:
    diAzTargetVel [inc/s] = deg/s × 524288 / 360
==============================================================================*)

// =============================================================================
// 段 A: 轴停止或下电时清快速停止位 bit8
// =============================================================================
IF sStatus.Disabled OR(NOT sStatus.Moving)THEN
	bAzCtrlBit8 := FALSE;
END_IF

// =============================================================================
// 段 B: 全局错误复位
// =============================================================================
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

// =============================================================================
// 段 C: CANopen 心跳超时（0x8130）自动恢复序列
// =============================================================================
IF GVL.eAzErrorcode = 16#8130 AND NOT tr THEN
	GVL.bAzCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bAzCtrlBit3 := FALSE;
	GVL.bAzCtrlBit0 := FALSE;
	GVL.bAzCtrlBit1 := FALSE;
	GVL.bAzCtrlBit2 := FALSE;
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bAzCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF

// =============================================================================
// 段 D: 主控制逻辑
// =============================================================================
IF GVL.Error_code=0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN

	// =========== 远控 ===========
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF

			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF
				// 下电状态下持续调用 vpid1（保持内部状态稳定）
				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);

			MODES.powerOn:  // 上电（DS402 三步序列）
				IF sStatus.Disabled THEN
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.positionMode: // 远控指向模式（加速度 12 deg/s²，Kp=0.6）
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						//自跟踪模式下，由误差电压直接驱动
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.6,//程引PI系数低带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度 12 deg/s²
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF

			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.programBootMode://PID速度模式-正常模式 程引（变增益 vpid1）
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						// 程引+自跟踪
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);							
					ELSE
						// 纯程引
						vpid1(rKpbase:=Persistentvars.rAzKpBase, rKibase:=Persistentvars.rAzKiBase, rKpMax:=Persistentvars.rAzKpMax, rKiMax:=Persistentvars.rAzKiMax, rVelThreshold:=Persistentvars.rAzThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rAzKpscale,rKiScale:=Persistentvars.rAzKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE

	// =========== 本控 ===========
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF

			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bAzCtrlBit3 := FALSE;
						GVL.bAzCtrlBit0 := FALSE;
						GVL.bAzCtrlBit1 := FALSE;
						GVL.bAzCtrlBit2 := FALSE;
					END_IF
				END_IF

			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					GVL.diAzTargetVel := 0;
					IF GVL.siAzMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siAzMode := 3;
					END_IF
					IF siAzMode = 3 THEN
						CASE istate OF
							0:
								GVL.bAzCtrlBit1 := TRUE;
								GVL.bAzCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bAzCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bAzCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diAzTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diAzTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.programBootMode://本控位置模式（普通 PID，Kp=0.6）
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diAzTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.6,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							//PID计算速度指令
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						END_IF

					END_IF
					GVL.diAzTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diAzTargetAcc := REAL_TO_UDINT(12 * 524288 / 360);   //加速度
					GVL.diAzTargetDec := REAL_TO_UDINT(12 * 524288 / 360);   //减速度
				END_IF

			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diAzTargetVel := 0;
						bAzCtrlBit8 := TRUE;
					ELSE
						bAzCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF

// =============================================================================
// 段 E: 全局错误时强制停轴，超时后强制下电
// =============================================================================
ELSIF GVL.Error_code<>0 AND GVL.eAzErrorcode = 0 AND NOT GVL.bAzCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diAzTargetVel := 0;
	bAzCtrlBit8 := TRUE;
	TON_0(IN:=bAzCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bAzCtrlBit3 := FALSE;
		GVL.bAzCtrlBit0 := FALSE;
		GVL.bAzCtrlBit1 := FALSE;
		GVL.bAzCtrlBit2 := FALSE;
	END_IF
END_IF

// 计算矩阵的行列式
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

(*
// 计算3x3矩阵的伴随矩阵
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

IF ABS(Determinant) > 1.0E-6 THEN
    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[i, j] := M[(i MOD 3) + 1, (j MOD 3) + 1] * M[((i + 1) MOD 3) + 1, ((j + 1) MOD 3) + 1] -
                                   M[(i MOD 3) + 1, ((j + 1) MOD 3) + 1] * M[((i + 1) MOD 3) + 1, (j MOD 3) + 1];
        END_FOR
    END_FOR

    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[j, i] := AdjointMatrix[i, j];
            AdjointMatrix[i, j] := AdjointMatrix[i, j] / Determinant;
        END_FOR
    END_FOR
END_IF
*)
// 计算3x3矩阵的伴随矩阵
Determinant := M[1, 1] * (M[2, 2] * M[3, 3] - M[2, 3] * M[3, 2]) -
               M[1, 2] * (M[2, 1] * M[3, 3] - M[2, 3] * M[3, 1]) +
               M[1, 3] * (M[2, 1] * M[3, 2] - M[2, 2] * M[3, 1]);

IF ABS(Determinant) > 1.0E-6 THEN
    FOR i := 1 TO 3 DO
        FOR j := 1 TO 3 DO
            AdjointMatrix[j, i] := ((M[(i MOD 3) + 1, (j MOD 3) + 1] * M[((i + 1) MOD 3) + 1, ((j + 1) MOD 3) + 1] -
                                   M[(i MOD 3) + 1, ((j + 1) MOD 3) + 1] * M[((i + 1) MOD 3) + 1, (j MOD 3) + 1]) / Determinant);
        END_FOR
    END_FOR
END_IF

// 计算X = AdjointMatrix * G
FOR i := 1 TO 3 DO
    X[i] := 0.0;
    FOR j := 1 TO 3 DO
        X[i] := X[i] + AdjointMatrix[i, j] * G[j];
    END_FOR
END_FOR

(*==============================================================================
  FB: El_Ctrl_FB（俯仰轴 Elevation 控制功能块）
  任务: Canopen 10ms（周期调用）
  作用:
    - 根据 sCtrl/sLocal 的 iMode，产生对应 CANopen 速度/控制字写入
    - 封装上/下电序列、软限位保护、CANopen 错误码自动恢复、心跳丢失处理
    - 内部调用 PID / vpid 进行位置→速度的闭环换算
  输入: sCtrl（远控命令结构体）、sLocal（本控命令结构体）
        sStatus（轴状态）、rRealPos（编码器实际角度）
  输出: 直接写 GVL.diElTargetVel / diElTargetAcc / diElTargetDec 及控制字位

  速度换算公式（通用）:
    diXxTargetVel [inc/s] = deg/s × 524288 / 360
    其中 524288 = 2^19（CANopen 电机编码器增量/转，具体由电机参数决定）
==============================================================================*)


// =============================================================================
// 段 A: 全局复位 — 轴停止或下电时清 bit8（快速停止位）
// bit8=1 激活快速停止，bit8=0 正常运行
// =============================================================================
IF sStatus.Disabled OR (NOT sStatus.Moving) THEN
	bElCtrlBit8 := FALSE;
END_IF

// =============================================================================
// 段 B: 错误复位（由 HMI 或 Modbus 写 bError_Reset）
// 将两个命令结构体模式设为 reset(6)，清 Error_code
// =============================================================================
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

// =============================================================================
// 段 C: CANopen 心跳超时错误（错误码 0x8130）自动恢复序列
// 步骤: 设 bit7(故障复位位) → 等 101 拍 → 清 bit7 → 再等 101 拍 → 结束
// 期间同时下电（清控制字 bit0~3），待驱动自愈后再由上层重新上电
// =============================================================================
IF GVL.eElErrorcode = 16#8130 AND NOT tr THEN
	GVL.bElCtrlBit7 := TRUE;  // 触发驱动故障复位
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bElCtrlBit3 := FALSE;
	GVL.bElCtrlBit0 := FALSE;
	GVL.bElCtrlBit1 := FALSE;
	GVL.bElCtrlBit2 := FALSE;	
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN     // 约 1s（10ms × 101）后清故障复位位
	icount1 := 0;
	tr := FALSE;
	GVL.bElCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN             // 再等 1s 让驱动彻底稳定
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF

// =============================================================================
// 段 D: 主控制逻辑
// 条件: 无全局错误 AND 无驱动错误 AND 不在心跳恢复序列中
// =============================================================================
IF GVL.Error_code=0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN

	// =========== 远控分支（bLocalCtrl=FALSE） ===========
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN   // 非上电模式时重置上电状态机
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF

			// ----- 模式 0: 下电 -----
			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;   // 发快速停止
					ELSE
						// 写入下电控制字（bit0~3=0 即断使能）
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF
				// 注: 下电模式仍持续运行 vpid1，但输出不写到 diElTargetVel
				// 目的是让 vpid1 内部积分不要突变（实际速度已通过控制字停掉）
				vpid1(rKpbase:=1, rKibase:=0.01, rKpMax:=1, rKiMax:=0.01, rVelThreshold:=10,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=0.02,rKiScale:=0.005,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);

			// ----- 模式 1: 上电（三步 CANopen DS402 状态机）-----
			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN
						// DS402 上电序列: Shutdown → Switch On → Enable Operation
						// 每步等待 20 拍（200ms）确保驱动应答
						CASE istate OF
							0:  // Shutdown: bit1=1, bit2=1（清故障 + 切换允许）
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:  // Switch On: bit0=1
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:  // Enable Operation: bit3=1
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					// 已上电：若还在运动则发快速停止等待停稳
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

			// ----- 模式 2: 指向模式（位置 PID 输出速度，远控）-----
			MODES.positionMode: // 远控指向模式
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						// 自跟踪模式：误差电压（rChanU）直接作为位置增量指令
						// 即: 目标 = rChanU（deg，来自跟踪接收机） + 当前位置
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,   // -1=始终开积分
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						// 指向模式：目标为上位机给定的角度
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.7,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					// 将 PID 输出速度(deg/s)换算为 CANopen 速度增量单位写入
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度 9 deg/s²
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF

			// ----- 模式 3: 速度模式（手动点动，远控）-----
			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					// 限幅处理：超过限速则取限速值
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			// ----- 模式 4: 程引模式（程序引导/插值跟踪，远控）-----
			// 使用变增益 vpid1，参数来自 PersistentVars（标定可调）
			MODES.programBootMode://PID速度模式-正常模式 程引
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						// 程引+自跟踪：误差电压叠加到插值目标位置上
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);						
					ELSE
						// 程引不开自跟踪：纯插值位置跟踪
						vpid1(rKpbase:=Persistentvars.rElKpBase, rKibase:=Persistentvars.rElKiBase, rKpMax:=Persistentvars.rElKpMax, rKiMax:=Persistentvars.rElKiMax, rVelThreshold:=Persistentvars.rElThre,rTarget:=sCtrl.rPIDCmdPos,rFeedback:=rRealPos,rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegitive:=sCtrl.rSoft_limit_Negative,
								bPIDEnable:=sCtrl.bPIDEnable,rVelLim:=sCtrl.rVel_Limit,rKpScale:=Persistentvars.rElKpscale,rKiScale:=Persistentvars.rElKiscale,rElPos:=GVL.rFctPosReal_1-90,
								iThrehold:=sCtrl.rPIDThre,rPIDOutDir=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			// ----- 模式 6: 重置 -----
			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

			// ----- 模式 5: 待机（停止运动，保持上电）-----
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE

	// =========== 本控分支（bLocalCtrl=TRUE）===========
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF

			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bElCtrlBit3 := FALSE;
						GVL.bElCtrlBit0 := FALSE;
						GVL.bElCtrlBit1 := FALSE;
						GVL.bElCtrlBit2 := FALSE;
					END_IF
				END_IF

			MODES.powerOn:  // 上电（与远控相同的三步序列）
				IF sStatus.Disabled THEN
					GVL.diElTargetVel := 0;
					IF GVL.siElMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siElMode := 3;
					END_IF
					IF siElMode = 3 THEN
						CASE istate OF
							0:
								GVL.bElCtrlBit1 := TRUE;
								GVL.bElCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bElCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bElCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diElTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diElTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diElTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.programBootMode://本控位置模式（普通 PID，不用变增益）
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diElTargetVel := 0;							
					ELSE
						IF NOT slocal.bStartAutoTrack THEN
							// 纯位置跟踪 PID
							 VelPID_2(rTarget:=sLocal.rPosCmd,
									 rFeedback:=rRealPos,
									 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
									 rPosLimNegative:=sLocal.rSoft_limit_Negative,
									 rKp:=0.7,
									 rKi:=0,
									 rKd:=0,
									 iThreshold:=sLocal.rPIDThre,
									 bPIDEnable:=sLocal.bPIDEnable,
									 rVelLim:=sLocal.Pos_Vel,
									 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
						ELSE
							// 本控自跟踪：误差电压叠加
							 VelPID_2(rTarget:=sLocal.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sLocal.rSoft_limit_Postive,
								rPosLimNegative:=sLocal.rSoft_limit_Negative,
								rVelLim:=sLocal.rVel_Limit,
								rKp:=1,//自跟踪PI系数3,0.02
								rKi:=0,
								rKd:=0,
								bPIDEnable:=sLocal.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sLocal.rPIDCmdVel);
						END_IF

					END_IF
					GVL.diElTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diElTargetAcc := REAL_TO_UDINT(9 * 524288 / 360);   //加速度
					GVL.diElTargetDec := REAL_TO_UDINT(9 * 524288 / 360);   //减速度
				END_IF

			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diElTargetVel := 0;
						bElCtrlBit8 := TRUE;
					ELSE
						bElCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF

// =============================================================================
// 段 E: 全局错误时强制停轴（Error_code≠0 但驱动本身无错，属于上层逻辑错误）
// 发快速停止，超时 1s 后强制下电
// =============================================================================
ELSIF GVL.Error_code<>0 AND GVL.eElErrorcode = 0 AND NOT GVL.bElCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diElTargetVel := 0;
	bElCtrlBit8 := TRUE;
	TON_0(IN:=bElCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bElCtrlBit3 := FALSE;
		GVL.bElCtrlBit0 := FALSE;
		GVL.bElCtrlBit1 := FALSE;
		GVL.bElCtrlBit2 := FALSE;
	END_IF
END_IF

(*==============================================================================
  PRG: El_ctrl_1（俯仰轴 El 顶层程序）
  任务: Canopen 10ms
  作用:
    1. 读 CANopen 反馈 → 换算实际速度/位置 (rFctVelReal_1 / rFctPosReal_1)
    2. 组装 Axis1Status（故障、使能、运动中等）
    3. 远/本控切换保护、自跟踪拉偏、AGC 峰值搜索
    4. 合成 PID 目标位置 rPIDCmdPos → 调用 El_Ctrl_FB
  数据流:
    Modbus/上位机 → Axis1Remote（在 Modbus_Slave 等处赋值）
    RealTimePosCal.rInterElPos + 各类偏置 → rPIDCmdPos → El_Ctrl_FB → GVL.diEl*
==============================================================================*)




(* 远控参量曾在此从 Modbus_Slave 直赋，现改由 Modbus_Slave 程序统一写入 Axis1Remote *)

// =============================================================================
// 段 1: 驱动状态字 → Axis1Status（供 El_Ctrl_FB 与 HMI 使用）
// DS402 状态: bit0/1/2 同时为 1 表示 Operation Enabled（伺服已使能）
// =============================================================================
Axis1Status.Error := GVL.bElStsBit3;
Axis1Status.ErrorID := GVL.eElErrorcode;
Axis1Status.bServo_Enable := GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2;
Axis1Status.bBrake := NOT (GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2);
Axis1Status.Disabled := NOT (GVL.bElStsBit0 AND GVL.bElStsBit1 AND GVL.bElStsBit2);
// 软限位写入命令结构体（与下面硬限位 93~180 一致）
Axis1Remote.rSoft_limit_Negative:=93;Axis1Remote.rSoft_limit_Postive:=180;
Axis1Local.rSoft_limit_Negative:=93;Axis1Local.rSoft_limit_Postive:=180;

// =============================================================================
// 段 2: CANopen 反馈 → 实际速度/位置（deg, deg/s）
// 公式: 物理量 = diActXxx / 524288 × 360；俯仰另加 Modbus 标定偏移 lrElOffset
// =============================================================================
rFctVelReal_1:=DINT_TO_REAL(diElActVel)/524288.0*360.0;
rFctPosReal_1:=DINT_TO_REAL(diElActPos)/524288.0*360.0 + modbus_slave.lrElOffset;

// =============================================================================
// 段 3: 指向命令硬限位（远控/本控 rPosCmd 钳位到 93°~180°）
// =============================================================================
Axis1Limit_pos:=180;
Axis1Limit_Neg:=93;
IF Axis1Remote.rPosCmd>Axis1Limit_pos THEN
	Axis1Remote.rPosCmd:=180;
ELSIF Axis1Remote.rPosCmd<Axis1Limit_Neg THEN
	 Axis1Remote.rPosCmd:=93;  
END_IF

IF Axis1Local.rPosCmd>Axis1Limit_pos THEN
	Axis1Local.rPosCmd:=180;
ELSIF Axis1Local.rPosCmd<Axis1Limit_Neg THEN
	 Axis1Local.rPosCmd:=93;  
END_IF

// =============================================================================
// 段 4: 停稳判定 → Axis1Status.Moving
// |速度|<0.035°/s 连续 100 拍(约1s) 认为停稳；bStop_1=TRUE → Moving=FALSE
// =============================================================================
IF  ABS(rFctVelReal_1)<0.035 THEN
	Stop1_Count:=Stop1_Count+1;
	IF Stop1_Count>100 THEN
		Stop1_Count:=101;
		bStop_1:=TRUE;;
	END_IF
ELSE
	Stop1_Count:=0;
	bStop_1:=FALSE;
END_IF
Axis1Status.Moving := NOT bStop_1;

// =============================================================================
// 段 5: PID 使能 — 仅指向(2)与程引(4)模式需要位置环
// =============================================================================
IF Axis1Remote.iMode=2 OR Axis1Remote.iMode=4 THEN
	Axis1Remote.bPIDEnable:=TRUE;
ELSE
	Axis1Remote.bPIDEnable:=FALSE;
END_IF

// =============================================================================
// 段 6: 远控 ↔ 本控 切换保护（GVL.bLocalCtrl）
// 切换瞬间若伺服仍使能 → 置切换标志 → 强制 mode=7(halt) 减速
// 停稳且下电完成后 → mode=0，清除标志
// =============================================================================
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

// 远控 → 本控（bLocalCtrl 上升沿）
IF Axis1Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_1=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis1Local.iMode:=0;
		Axis1Remote.iMode:=0;
		IF Axis1Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis1Local.iMode:=7;
		Axis1Remote.iMode:=7;
	END_IF
END_IF

// 本控 → 远控（bLocalCtrl 下降沿）
IF Axis1Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_1=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis1Local.iMode:=0;
		Axis1Remote.iMode:=0;
		IF Axis1Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis1Remote.iMode:=7;
		Axis1Local.iMode:=7;
	END_IF
END_IF

// =============================================================================
// 段 7: AGC 峰值搜索（与方位 Az_ctrl_1 协同，bstartSearchEl 由方位触发）
// mode2: 插值目标 = rPosCmd；mode4: 插值目标 = RealTimePosCal.rInterElPos
// 仅当俯仰高于 rElthreshold（相对水平）且在程引下才在 mode4 启用搜索
// =============================================================================
IF Axis1Remote.iMode=2 THEN
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_tb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
						rCurrentPos:=rFctPosReal_1,rInterPos:=Axis1Remote.rPosCmd,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_tb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
				rCurrentPos:=rFctPosReal_1,rInterPos:=Axis1Remote.rPosCmd,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget_tb,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
		ELSIF Axis1Remote.iMode=4 AND rFctPosReal_1-90>rElthreshold  THEN
			IF GVL.Chan1AGC>=(GVL.Chanthreshold-0.1) THEN
					agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
						rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			ELSE
				bstartagcmaxsearch:=FALSE;
				agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
				rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,
				rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
				rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
			END_IF
		ELSIF Axis1Remote.iMode =0  OR Axis1Remote.iMode =7 THEN
			bstartagcmaxsearch:=FALSE;
			agcmaxsearch_pb(bstart:=Az_ctrl_1.agcmaxsearch_pb.bSucess,rAGCNow:=GVL.Chan1AGC,btrig:=Az_ctrl_1.bstartSearchEl,
			rCurrentPos:=rFctPosReal_1,rInterPos:=RealTimePosCal.rInterElPos,	
			rStepBiasNow:=rStepBias,bAutoTracking:=GVL.bStartTrack,bStop:=FALSE,
			rStepBias=>rSearchNextStepTarget,rAGCMaxBias=>rMaxPosTest,bSucess=>);
		END_IF

// =============================================================================
// 段 8: 自跟踪拉偏（远控）
// mode4+程引: 用 AutoTrackingCal.rChanUe 累积 rAuToStepBias（限幅）
// mode2+指向: 直接用 rChanU 作 PID 目标增量（在 El_Ctrl_FB 内 rChanU+位置）
// 关跟踪: rAuToStepBias 渐零，rStepBias 渐近 Modbus_Slave.rBias_1
// =============================================================================
IF GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	IF rAuToStepBias > rAutoTrackingBiasMax THEN
		rAuToStepBias := rAutoTrackingBiasMax;
	ELSIF rAuToStepBias < -rAutoTrackingBiasMax THEN
		rAuToStepBias := -rAutoTrackingBiasMax;
	ELSE
		rAuToStepBiasTemp:=0.02*AutoTrackingCal.rDirSenFac*AutoTrackingCal.rChanUe;
		rAuToStepBias:=rAuToStepBias+AutoTrackingCal.rDirSenFac*rKAuToStepBias*AutoTrackingCal.rChanUe/1000.0;
	END_IF
ELSIF NOT GVL.bStartTrack AND Axis1Remote.iMode=4 THEN
	IF 	rAuToStepBias>0 THEN//关闭自跟踪后自跟踪拉偏量逐渐归0
		rAuToStepBias:=rAuToStepBias-rAutoStep;
	ELSIF rAuToStepBias<0 THEN
		rAuToStepBias:=rAuToStepBias+rAutoStep;
	ELSE
		rAuToStepBias:=0;
	END_IF

	IF Modbus_Slave.rBias_1>rStepBias THEN
		rStepBias:=rStepBias+rStep;
		IF rStepBias>=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	ELSIF Modbus_Slave.rBias_1<rStepBias THEN
		rStepBias:=rStepBias-rStep;
		IF rStepBias<=Modbus_Slave.rBias_1 THEN
			rStepBias:=Modbus_Slave.rBias_1;
		END_IF
	END_IF
	rAuToStepBiasTemp:=0;
ELSIF GVL.bStartTrack AND Axis1Remote.iMode=2 THEN
	Axis1Remote.bStartAutoTrack := TRUE;
	Axis1Remote.rChanU := AutoTrackingCal.rChanUe;
ELSE
	Axis1Remote.bStartAutoTrack := FALSE;	
	rAuToStepBias:=0;
	rStepBias:=0;
	rAuToStepBiasTemp:=0;
END_IF

// 本控自跟踪（仅程引 mode4）
IF GVL.bStartLocalAutoTrack AND Axis1Local.iMode = 4 THEN
	Axis1Local.bStartAutoTrack := TRUE;
	Axis1Local.rChanU := AutoTrackingCal.rChanUeLocal;
ELSE
	Axis1Local.bStartAutoTrack := FALSE;
END_IF

// =============================================================================
// 段 9: 合成 PID 目标位置并限位 → 调用 El_Ctrl_FB
// rPIDCmdPos = 程引插值 + 手动偏置 + 自跟踪偏置 + AGC搜索偏置 + 安全检查偏置
// =============================================================================
Axis1Remote.rPIDCmdPos:=RealTimePosCal.rInterElPos+rStepBias+rAuToStepBias+rSearchNextStepTarget+SECURITYCHECK.el_out+rAuToStepBiasTemp;
IF Axis1Remote.rPIDCmdPos<93 THEN
	Axis1Remote.rPIDCmdPos:=93;
ELSIF Axis1Remote.rPIDCmdPos>180 THEN
	Axis1Remote.rPIDCmdPos:=180;
END_IF

Axis1_Ctrl(sLocal:=Axis1Local, sCtrl:=Axis1Remote, sStatus:=Axis1Status, sVisible:=Axis1Visible, rRealPos:=rFctPosReal_1, rPosLimK:=0.34);

//tLastTime:=tLastTime/1000000;
//tCurTime:=tCurTime/1000000;
//tTargetTime:=tTargetTime/1000000;
iDelTarCurTime:=ULINT_TO_LREAL(tTargetTime)-ULINT_TO_LREAL(tCurTime); //x1-x
IF (tCurTime-tLastTime)<>0 THEN
	iDelCurLastTime:=ULINT_TO_LREAL(tCurTime)-ULINT_TO_LREAL(tLastTime);  //x-x0
ELSE
	iDelCurLastTime:=1.0;
END_IF

IF iDelTarCurTime<>0 THEN
	rK:=(rCurPos-rLastPos)/(iDelCurLastTime);
ELSE
	rK:=0;
END_IF
rTargetpos:=rCurPos+rK*iDelTarCurTime;  //y1 + ((y1-y0)/(x1-x0))*(x-x1)

FOR i:=1 TO 5 DO
	X[i]:=ULINT_TO_LREAL(aUTC_TIME[i]);
	Y[i]:=aPosCmd[i];
END_FOR


Three(X:=X,Y:=Y,y0:=y0,yn:=yn,D=>D,h=>h,A=>A,g=>g,M=>M);

FOR i:=1 TO (n-1) DO
	p1[i]:=M[i]*(X[i+1]-xt)*(X[i+1]-xt)*(X[i+1]-xt)/(6*h[i]);
	p2[i]:=M[i+1]*(xt-X[i])*(xt-X[i])*(xt-X[i])/(6*h[i]);
	p3[i]:=(A[i,1]-M[i]/6*(h[i])*(h[i]))*(X[i+1]-xt)/h[i];
	p4[i]:=(A[i+1,1]-M[i+1]/6*(h[i])*(h[i]))*(xt-X[i])/h[i];


END_FOR


FOR i:=1 TO (n-1) DO
	IF (xt<=X[i+1])AND (xt>=X[i]) THEN
		nout:=i;
		sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
	ELSIF xt>X[5] THEN
		nout:=4;
	ELSIF xt<X[1]THEN
		nout:=1;
	END_IF
END_FOR


//要不要判断插值模块是否有效？
sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
(*
IF xt>X[5] THEN
	nout:=4;
	sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
ELSIF xt<X[1] THEN
	nout:=1;
	sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
END_IF
*)

//该功能块查找到轨道时间数组内最大最小值以及索引位置
//找出最大最小值
MaxVal := 0; // 初始化最大值
MinVal := 0; // 初始化最小值
MaxIndex := 0; // 初始化最大值的索引
MinIndex := 0; // 初始化最小值的索引

FOR i := 1 TO 5 DO
    IF Arr[i] <> 0 THEN
        IF MaxVal = 0 THEN
            MaxVal := Arr[i];
            MaxIndex := i;
        ELSIF Arr[i] > MaxVal THEN
            MaxVal := Arr[i];
            MaxIndex := i;
        END_IF

        IF MinVal = 0 THEN
            MinVal := Arr[i];
            MinIndex := i;
        ELSIF Arr[i] < MinVal THEN
            MinVal := Arr[i];
            MinIndex := i;
        END_IF
    END_IF
END_FOR

// MaxVal 和 MinVal 包含了最大值和最小值，不考虑值为0的元素
// MaxIndex 和 MinIndex 包含了最大值和最小值的索引


//当前时间和最大最小比较 
IF ulRealTime<MinVal*1000000 THEN //小于插值范围 取最小时间
	//
	ulInterRealTime:=MinVal*1000000; //应该修改插值位置 而不是时间
ELSIF ulRealTime>MaxVal*1000000THEN //大于插值范围 取最大时间
	//
	ulInterRealTime:=MaxVal*1000000;//应该修改插值位置 而不是时间
ELSE
	//如果内部有0 则不插值选取最新的数据
	FOR j:=1 TO 5 DO
		IF (Arr[i]=0) AND (j<5) THEN
			ulInterRealTime:=Arr[5];//应该修改插值位置 而不是时间
			MaxIndex:=5;
			EXIT;
		ELSIF (Arr[i]=0) AND (j=5) THEN
			//没有输入数据 需要报错吗？
		END_IF
	END_FOR
	//
END_IF

FOR nn:=1 TO 10 DO
	//XModbus[nn]:=ULINT_TO_LREAL(XModbusUL[nn])*1000000/1000.0;
	XModbus[nn]:=ULINT_TO_LREAL(XModbusUL[nn]-XModbusUL[1])+1.0;
END_FOR
	xt:=xt-ULINT_TO_LREAL(XModbusUL[1])+1.0;
IF ErrCode>0 THEN
	ErrCode:=0;
END_IF


FOR mm:=2 TO 8 DO
	IF XModbus[mm] = XModbus[mm + 1] THEN
		// 找到相等的两个数，进行线性插值
		XModbus[mm + 1] := (XModbus[mm] + XModbus[mm + 2]) / 2.0;
	END_IF;
END_FOR
IF XModbus[1] = XModbus[2] THEN
	// 找到相等的两个数，进行线性插值
	XModbus[1] := XModbus[2]-(XModbus[3]-XModbus[2]);
END_IF;
IF XModbus[9] = XModbus[10] THEN
	// 找到相等的两个数，进行线性插值
	XModbus[10] := XModbus[9]+(XModbus[9]-XModbus[8]);
END_IF;

IF ErrCode <> 0 THEN
	iCountOutMaxRange:=0;
	iCountOutMinRange:=0;
END_IF


//在何处清空序列呢
//bSetZero:=FALSE; //默认不清空

IF  XModbus[10]=0 THEN
	//报错
	ErrCode:=107;//序列为空
ELSE
	IF XModbus[10]-XModbus[1]>2000000 THEN
		sout:=YModbus[10];
	ELSE
		IF xt<XModbus[1] THEN
			sout:=YModbus[1];
			//报故障 累计超时报错
			iCountOutMinRange:=iCountOutMinRange+1;
			IF iCountOutMinRange>5000 THEN
				iCountOutMaxRange:=5001;
				//ErrCode:=108;//偏小超时报错
			END_IF
		ELSIF xt>XModbus[10]  THEN
			sout:=YModbus[10];
			//报故障 累计超时报错
			iCountOutMaxRange:=iCountOutMaxRange+1;
			IF iCountOutMaxRange>5000 THEN
				iCountOutMaxRange:=5001;
				//ErrCode:=109;//偏大超时报错
			END_IF
		ELSE //若所求目标位置在Modbus中间
			iCountOutMaxRange:=0;
			iCountOutMinRange:=0;
			//若不满五个点
			IF XModbus[6]=0 THEN
				sout:=XModbus[10];
			ELSE
				//若满五个点
				//寻找当前插值区间
				FOR j:=2 TO 10 DO
					IF xt<XModbus[j] THEN
						k:=j;
						EXIT;
					END_IF
				END_FOR

				IF k=2 THEN
					X[1]:=XModbus[k-1];X[2]:=XModbus[k];X[3]:=XModbus[k+1];X[4]:=XModbus[k+2];X[5]:=XModbus[k+3];
					y[1]:=YModbus[k-1];Y[2]:=YModbus[k];Y[3]:=YModbus[k+1];Y[4]:=YModbus[k+2];Y[5]:=YModbus[k+3];
				ELSIF k>2 AND k<=8 THEN
					X[1]:=XModbus[k-2];X[2]:=XModbus[k-1];X[3]:=XModbus[k];X[4]:=XModbus[k+1];X[5]:=XModbus[k+2];
					Y[1]:=YModbus[k-2];Y[2]:=YModbus[k-1];Y[3]:=YModbus[k];Y[4]:=YModbus[k+1];Y[5]:=YModbus[k+2];
				ELSIF k=9 THEN
					X[1]:=XModbus[k-3];X[2]:=XModbus[k-2];X[3]:=XModbus[k-1];X[4]:=XModbus[k];X[5]:=XModbus[k+1];
					Y[1]:=YModbus[k-3];Y[2]:=YModbus[k-2];Y[3]:=YModbus[k-1];Y[4]:=YModbus[k];Y[5]:=YModbus[k+1];
				ELSIF k=10 THEN
					X[1]:=XModbus[k-4];X[2]:=XModbus[k-3];X[3]:=XModbus[k-2];X[4]:=XModbus[k-1];X[5]:=XModbus[k];
					Y[1]:=YModbus[k-4];Y[2]:=YModbus[k-3];Y[3]:=YModbus[k-2];Y[4]:=YModbus[k-1];Y[5]:=YModbus[k];
				END_IF


				//开始解算
				Three(X:=X,Y:=Y,y0:=y0,yn:=yn,D=>D,h=>h,A=>A,g=>g,M=>M);
				FOR i:=1 TO (n-1) DO
					p1[i]:=M[i]*(X[i+1]-xt)*(X[i+1]-xt)*(X[i+1]-xt)/(6*h[i]);
					p2[i]:=M[i+1]*(xt-X[i])*(xt-X[i])*(xt-X[i])/(6*h[i]);
					p3[i]:=(A[i,1]-M[i]/6*(h[i])*(h[i]))*(X[i+1]-xt)/h[i];
					p4[i]:=(A[i+1,1]-M[i+1]/6*(h[i])*(h[i]))*(xt-X[i])/h[i];
				END_FOR
				FOR i:=1 TO (n-1) DO
					IF (xt<=X[i+1])AND (xt>=X[i]) THEN
						nout:=i;
						sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
					ELSIF xt>X[5] THEN
						nout:=4;
					ELSIF xt<X[1]THEN
						nout:=1;
					END_IF
				END_FOR
				sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
				(*
				IF xt>X[5] THEN
					nout:=4;
					sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
				ELSIF xt<X[1] THEN
					nout:=1;
					sout:=p1[nout]+p2[nout]+p3[nout]+p4[nout]; 
				END_IF
				*)
				END_IF
			END_IF

		END_IF

//修正输入量为长度为10的数组

END_IF

(*==============================================================================
  PRG: SecurityCheck（远控汇总 / 安全联锁 / 捕获扫描 / 自跟踪启停）
  任务: Canopen 10ms（与 *_ctrl_1 同周期，先于或并行执行需注意调用顺序）

  主要职责:
    1. Modbus_Slave → Axis1/2/3Remote 远控命令统一赋值（阶段5 中 *_ctrl_1 注释块已移至此）
    2. 伺服电流监测（%IW10/20/30 × %ID4/9/14）
    3. 俯仰/方位跟踪误差 AzError、ElError（供螺旋/直线扫描 FB）
    4. 预限位 → GVL.Error_code 201/202，状态上报 Modbus DI1
    5. 捕获扫描 SpiralScan：输出 az_out / el_out → 叠加到 rPIDCmdPos
    6. 根据 AGC/锁相/扫描完成 自动置位 GVL.bStartTrack

  与 *_ctrl_1 关系:
    El:  rPIDCmdPos += SecurityCheck.el_out
    Az:  rPIDCmdPos -= SecurityCheck.az_out
==============================================================================*)

// =============================================================================
// 段 1: 安全逻辑用位置（与显示用 rFctPosReal 可能差符号/零点）
// =============================================================================
rAz_realpos := -1 * GVL.rFctPosReal_2;
rEl_realpos := GVL.rFctPosReal_1 - 90;

// =============================================================================
// 段 2: 三轴伺服电流监测（仅使能时读 AD，%IW×%ID/1e6）
// %IW10/%ID4=俯仰, %IW20/%ID9=方位, %IW30/%ID14=倾斜
// =============================================================================
IF Axis1Status.bServo_Enable THEN
	rELCurrent:=DINT_TO_REAL((INT_TO_DINT(%IW10)* %ID4))/1000000.0;  //俯仰轴电流监测
ELSE
	rELCurrent:=0;
END_IF

IF Axis2Status.bServo_Enable THEN
	rAzCurrent:=DINT_TO_REAL((INT_TO_DINT(%IW20)* %ID9))/1000000.0;  //方位轴电流监测
ELSE
	rAzCurrent:=0;
END_IF

IF Axis3Status.bServo_Enable THEN
	rTlCurrent:=DINT_TO_REAL((INT_TO_DINT(%IW30)* %ID14))/1000000.0;  //倾斜轴电流监测
ELSE
	rTlCurrent:=0;
END_IF

// =============================================================================
// 段 3: 跟踪误差（供 SpiralScan 判断扫描方向与完成度）
// mode2 指向: 命令位置 vs 实际位置
// mode4 程引: 插值目标+偏置 vs 实际位置（含手动/自跟踪偏置）
// =============================================================================
IF Axis2Remote.iMode = 2 THEN
	AzError:=(-1) * (Axis2Remote.rPosCmd-rFctPosReal_2);
	ElError:=Axis1Remote.rPosCmd-rFctPosReal_1;	
END_IF

IF Axis2Remote.iMode = 4 THEN
	AzError:=rFctPosReal_2-RealTimePosCal.rInterazPos-(az_ctrl_1.rStepBias+az_ctrl_1.rAuToStepBias);
	ElError:=RealTimePosCal.rInterElPos-rFctPosReal_1+ (El_ctrl_1.rStepBias+EL_ctrl_1.rAuToStepBias);
END_IF
(*
rAzErrorReal := rAzErrorReal + rAlpha * (AzError - rAzErrorReal);
rElErrorReal := rElErrorReal + rAlpha * (ElError - rElErrorReal);
*)

// =============================================================================
// 段 4: 远控故障复位（Modbus bCommReset → GVL.bError_Reset）
// =============================================================================
IF NOT GVL.bLocalCtrl THEN
	IF Modbus_Slave.bCommReset THEN
		GVL.bError_Reset:=TRUE;
	ELSE
		GVL.bError_Reset:=FALSE;
	END_IF
END_IF

// =============================================================================
// 段 5: 远控 rPosCmd 赋值（含 AGC 搜索偏置或测试扫描偏置）
// 非 bSearch: Modbus 目标 + eltest/aztest
// bSearch:   Modbus 目标 + *_ctrl_1 的 rSearchNextStepTarget_tb
// =============================================================================
IF NOT modbus_slave.bSearch THEN
	Axis1Remote.rPosCmd:=Modbus_Slave.rPosCmd_1 + eltest;
	Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2 - aztest;
ELSE
	Axis1Remote.rPosCmd:=Modbus_Slave.rPosCmd_1 + El_ctrl_1.rSearchNextStepTarget_tb;
	Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2 + Az_ctrl_1.rSearchNextStepTarget_tb;
END_IF

// =============================================================================
// 段 6: 远控三轴命令参量 — Modbus_Slave → AxisXRemote（核心汇总）
// 俯仰/方位 rPosCmd 已在段 5 赋值；此处写 mode/速度/PID/加减速等
// =============================================================================
Axis1Remote.iMode:=Modbus_Slave.iMode_1;
Axis1Remote.rVelCmd:=Modbus_Slave.rVelcmd_1;
//Axis1Remote.rPosCmd:=Modbus_Slave.rPosCmd_1;
Axis1Remote.rP:=Modbus_Slave.rP_1;
Axis1Remote.rI:=Modbus_Slave.rI_1;
Axis1Remote.rD:=Modbus_Slave.rD_1;
Axis1Remote.rPIDThre:=Modbus_Slave.rThreshold_1;
Axis1Remote.rAcceleration:=Modbus_Slave.rAcceleration_1;
Axis1Remote.rDeceleration:=Modbus_Slave.rDeceleration_1;
Axis1Remote.rVel_Limit:=Modbus_Slave.rVelLim_1;

Axis2Remote.iMode:=Modbus_Slave.iMode_2;
Axis2Remote.rVelCmd:=Modbus_Slave.rVelcmd_2;
//Axis2Remote.rPosCmd:=Modbus_Slave.rPosCmd_2;
Axis2Remote.rP:=Modbus_Slave.rP_2;
Axis2Remote.rI:=Modbus_Slave.rI_2;
Axis2Remote.rD:=Modbus_Slave.rD_2;
Axis2Remote.rPIDThre:=Modbus_Slave.rThreshold_2;
Axis2Remote.rAcceleration:=Modbus_Slave.rAcceleration_2;
Axis2Remote.rDeceleration:=Modbus_Slave.rDeceleration_2;
Axis2Remote.rVel_Limit:=Modbus_Slave.rVelLim_2;

Axis3Remote.iMode:=Modbus_Slave.iMode_3;
Axis3Remote.rVelCmd:=Modbus_Slave.rVelcmd_3;
Axis3Remote.rPosCmd:=Modbus_Slave.rPosCmd_3;
Axis3Remote.rP:=Modbus_Slave.rP_3;
Axis3Remote.rI:=Modbus_Slave.rI_3;
Axis3Remote.rD:=Modbus_Slave.rD_3;
Axis3Remote.rPIDThre:=Modbus_Slave.rThreshold_3;
Axis3Remote.rAcceleration:=Modbus_Slave.rAcceleration_3;
Axis3Remote.rDeceleration:=Modbus_Slave.rDeceleration_3;

(* 本控 HMI 赋值块已注释，本控参数由其他 POU 写入 AxisXLocal *)

// =============================================================================
// 段 7: 俯仰预限位 → Error_code 201(正)/202(负)，置位上报标志
// bPrelimit_1 由硬件 IO 映射；触发后根据当前位置方向区分正负限位
// =============================================================================
IF bPrelimit_1 THEN
	IF rFctPosReal_1>0 THEN
		bPrelimit_Positive_1:=TRUE;
		Error_code:=201;
	ELSE
		bPrelimit_Negative_1:=TRUE;
		Error_code:=202;
	END_IF;
ELSE
	bPrelimit_Negative_1:=FALSE;
	bPrelimit_Positive_1:=FALSE;
	;
END_IF

// =============================================================================
// 段 8: 方位预限位（仅置标志，Error_code 203/204 已注释）
// =============================================================================
IF bPrelimit_2 THEN
	IF rFctPosReal_2>0 THEN
		//Error_code:=203;
		bPrelimit_Positive_2:=TRUE;;
	ELSE
		//Error_code:=204;
		bPrelimit_Negative_2:=TRUE;;
	END_IF;
ELSE
	bPrelimit_Negative_2:=FALSE;
	bPrelimit_Positive_2:=FALSE;
	;
END_IF

// =============================================================================
// 段 9: 锁定判定 — 信噪比 EB_N0≥28 或 (AGC≥门限 且 误差电压≤rErrorThre)
// bErrorLock: 仅误差电压小（适合进入跟踪）
// =============================================================================
bLockSearch := READ_485.Chan1EB_N0 >= 28 OR ((GVL.Chan1AGC >= GVL.Chanthreshold) AND (SQRT(GVL.Chan1Ua * GVL.Chan1Ua + GVL.Chan1Ue * GVL.Chan1Ue) <= PersistentVars.rErrorThre));
bErrorLock  := (SQRT(GVL.Chan1Ua * GVL.Chan1Ua + GVL.Chan1Ue * GVL.Chan1Ue) <= PersistentVars.rErrorThre);

// =============================================================================
// 段 10: 捕获扫描使能 — 双轴均为程引(4)、AGC 达标或接收机锁定、且尚未自跟踪
// =============================================================================
IF Axis1Remote.iMode = 4 AND Axis2Remote.iMode = 4 AND (gvl.Chan1AGC > PersistentVars.rStartThre OR READ_485.recBuf[1] = 1) AND NOT GVL.bStartTrack THEN
	enable := TRUE;
ELSIF Axis1Remote.iMode <> 4 THEN
	enable := FALSE;
END_IF

// =============================================================================
// 段 11: 调用扫描 FB — 直线(SpiralScan) 或 螺旋(SpiralScan_1)
// 输出 az_out / el_out 在 *_ctrl_1 中叠加到 rPIDCmdPos
// =============================================================================
IF NOT PersistentVars.bSearchType THEN
	// ===== 调用直线扫描 =====
	fbScan(
		enable      := enable,
		delta       := PersistentVars.rAzScanRange,
		delta1      := PersistentVars.rElScanRange,
		n_steps     := PersistentVars.rStep,
		agc      := GVL.Chan1AGC,
		locked     := bLockSearch,
		AzError := AzError,
		elError := elError,
		bTrackState := GVL.bStartTrack,
		azimuth     => az_out,
		elevation   => el_out,
		done        => done_out,
		bType  =>bType_out
	);
ELSE
	// ===== 调用螺旋扫描====
	fbScan1(
		enable      := enable,
		delta       := rdelta,
		n_steps     := rStep,
		agc      := GVL.Chan1AGC,
		locked     := bLockSearch,
		AzError := AzError,
		elError := elError,
		azimuth     => az_out,
		elevation   => el_out,
		done        => done_out,
		bType  =>bType_out
	);
END_IF

// =============================================================================
// 段 12: 自跟踪启停状态机（仅双轴程引 mode4）
// 扫描完成+锁定 → 置 GVL.bStartTrack
// 失锁持续计数超阈值 → 清 GVL.bStartTrack
// PersistentVars.bTrackingMode: TRUE=自动开跟踪, FALSE=需 ACU 边沿 bStartTrackAcu
// =============================================================================
IF Axis1Remote.iMode = 4 AND Axis2Remote.iMode = 4 THEN
	bFinish := done_out AND (ABS(AzError + az_out) <= 0.08) AND (ABS(ElError + el_out) <= 0.08);//扫描到位
	// 上升沿检测
	RiseEdge(CLK := Modbus_Slave.bStartTrackAcu);

	IF RiseEdge.Q THEN
		bStartTrackTemp := TRUE;
	END_IF;

	IF PersistentVars.bTrackingMode THEN
		IF bType_out THEN
			IF done_out AND bLockSearch THEN
				GVL.bStartTrack := TRUE;
				icountLostLocking := 0;
			ELSIF done_out AND NOT (SQRT(GVL.Chan1Ua * GVL.Chan1Ua + GVL.Chan1Ue * GVL.Chan1Ue) <= PersistentVars.rErrorThre) THEN
				icountLostLocking := icountLostLocking + 1;
				IF icountLostLocking >= 1000 THEN //失锁持续5秒退出自跟踪
					icountLostLocking := 1001;
					GVL.bStartTrack := FALSE;
				END_IF
			END_IF
		ELSE
			IF done_out THEN
				iconutwait := iconutwait + 1;
			END_IF
			IF iconutwait >= 500 THEN
				Iconutwait := 501;
			END_IF
			IF iconutwait >= 100 AND bErrorLock AND (bFinish OR iconutwait >= 500) THEN
				GVL.bStartTrack := TRUE;
				icountLostLocking1 := 0;
			ELSIF iconutwait >= 100 AND NOT bErrorLock THEN
				icountLostLocking1 := icountLostLocking1 + 1;
				IF icountLostLocking1 >= 300 THEN //失锁持续5秒退出自跟踪
					icountLostLocking1 := 301;
					GVL.bStartTrack := FALSE;
				END_IF
			END_IF
		END_IF
	ELSE
		IF bType_out THEN
			IF done_out AND bLockSearch THEN
				GVL.bStartTrack := bStartTrackTemp;
				icountLostLocking := 0;
			ELSIF done_out AND NOT (SQRT(GVL.Chan1Ua * GVL.Chan1Ua + GVL.Chan1Ue * GVL.Chan1Ue) <= PersistentVars.rErrorThre) THEN
				icountLostLocking := icountLostLocking + 1;
				IF icountLostLocking >= 1000 THEN //失锁持续5秒退出自跟踪
					icountLostLocking := 1001;
					GVL.bStartTrack := FALSE;
				END_IF
			END_IF
		ELSE
			IF done_out THEN
				iconutwait := iconutwait + 1;
			END_IF
			IF iconutwait >= 500 THEN
				Iconutwait := 501;
			END_IF
			IF iconutwait >= 100 AND bErrorLock AND (bFinish OR iconutwait >= 500) THEN
				GVL.bStartTrack := bStartTrackTemp;
				icountLostLocking1 := 0;
			ELSIF iconutwait >= 100 AND NOT bErrorLock THEN
				icountLostLocking1 := icountLostLocking1 + 1;
				IF icountLostLocking1 >= 300 THEN //失锁持续5秒退出自跟踪
					icountLostLocking1 := 301;
					GVL.bStartTrack := FALSE;
				END_IF
			END_IF
		END_IF
	END_IF
ELSE
	bStartTrackTemp := FALSE;
	GVL.bStartTrack := Modbus_Slave.bStartTrackAcu;
	icountLostLocking := 0;
	icountLostLocking1 := 0;
	Iconutwait := 0;
END_IF

(* fbScantest 测试块已注释 *)

IF (bPIDEnable>0) THEN //如果PID使能
	IF rTarget=rFeedback THEN
		rPIDOutput:=0;	
	ELSE

		rErrorNow:=rTarget-rFeedback;//计算当前误差 en
		rProportionNew:=rErrorNow;//比例项
		//积分项
		IF rFeedback>rPosLimNegative AND rFeedback<rPosLimPositive THEN //若在软限位之内，工作时开启积分项
			IF (ABS(rTarget-rFeedback)<iThreshold OR iThreshold = -1) THEN//位置差小于积分阈值开始积分，或者设置阈值为-1，不启用这个控制
				rIntegralNew:= rIntegralNew+rErrorNow; //积分项
			ELSE
				rIntegralNew:=0;
			END_IF;
		ELSE //不在软限位范围内,则积分项为0
			rIntegralNew:=0;
		END_IF

		//PID输出
		rPIDOutPut:=rKp*rProportionNew+rKi*rIntegralNew;


		//PID限速

			IF rPIDOutput<(-rVelLim) THEN
				rPIDOutput:=-rVelLim;
			ELSIF rPIDOutput>rVelLim THEN
				rPIDOutput:=rVelLim;
			END_IF


		IF rFeedback>rPosLimPositive AND rPIDOutput>0 THEN 
			rPIDOutput:=0;
		END_IF
		IF rFeedback<rPosLimNegative AND rPIDOutput<0 THEN
			rPIDOutput:=0;
		END_IF

		rLastError:=rErrorNow;//将当前误差赋值给上一次误差

	END_IF
ELSE//非使能清零PID各项
	rProportionNew:=0.0;
	rIntegralNew:=0.0;
	rPIDOutput:=0.0;
END_IF

(*==============================================================================
  PRG: AutoTrackingCal（自跟踪误差电压处理）
  任务: Canopen 10ms
  输入: GVL.Chan1Ua/Ue/AGC/Lock（由 READ_485 写入）
  输出（程序内变量，供 *_ctrl_1 引用）:
    rChanUa  — 方位误差电压（已÷灵敏度、÷cos(俯仰)）
    rChanUe  — 俯仰误差电压（已÷灵敏度）
    rAzSum / rElSum — 累积拉偏量（当前未回写到 GVL）
  使用:
    El_ctrl_1: rChanUe → rChanU / rAuToStepBias
    Az_ctrl_1: -rChanUa → rChanU / rAuToStepBias
  注意:
    rDirSenFac、rk 在导出代码中未见赋值，可能来自 Modbus/HMI 或需人工确认
    rChanUaLocal / rChanUeLocal 未见赋值，本控自跟踪可能依赖未初始化值（原工程保留）
==============================================================================*)
(* 旧版按 iState 直接映射 GVL 通道，已注释 *)

//iState:=modbusSlave.Trace_Num;//跟踪支路选择
iState:=1;                             // 固定使用跟踪接收机 1

CASE iState OF 
	1://使用跟踪接收机1 且锁定标识为True
		// ----- 自跟踪使能且（锁定或 SecurityCheck 误差电压足够小）-----
		IF GVL.bStartTrack AND (GVL.Chan1Lock OR Securitycheck.bErrorLock) THEN
			// 方位：原始 Ua → ÷灵敏度 → ÷cos(El) 补偿大仰角时方位耦合
			rChanUa:=GVL.Chan1Ua;
			rChanUa:=rChanUa/rDirSenFac;
			rCurentEl:=(rFctPosReal_1-90)*3.1415926535897/180.0;
			rChanUa:=rChanUa/COS(rCurentEl);

			// 俯仰：原始 Ue → ÷灵敏度
			rChanUe:=GVL.Chan1Ue;
			rChanUe:=rChanUe/rDirSenFac;
			rChanAGC:=GVL.Chan1AGC;

			// 累积量（供扩展；当前 *_ctrl_1 主要用瞬时 rChanUa/Ue）
			rAzSum:=rAzSum+rk*rChanUa/1000.0;
			rElSum:=rElSum+rk*rChanUe/1000.0;
		ELSE
			rAzSum:=0;
			rElSum:=0;
			rChanUa:=0;
			rChanUe:=0;
		END_IF

	2://使用跟踪接收机2 且锁定标识为True
		rChanUa:=GVL.Chan2Ua;
		rChanUe:=GVL.Chan2Ue;
		rChanAGC:=GVL.Chan2AGC;

	3://锁定标识符为False
		//bChanLock:=FALSE;
END_CASE

(*==============================================================================
  PRG: Ti_ctrl_1（倾斜轴 Ti 顶层程序）
  任务: Canopen 10ms
  作用: 倾斜轴反馈、状态、远/本控切换保护，调用 Ti_Ctrl_FB
  与 El/Az 差异:
    - 无 AGC 搜索、无自跟踪拉偏（相关代码已注释）
    - 未在此程序内赋值 rPIDCmdPos（由 Modbus/其他模块写入后仅做限位）
    - 远控→本控切换时仅强制 Axis3Remote.iMode:=7（本控 mode 未同步置 7）
    - 本控上限钳位有一处写 Axis2Local（原工程保留，勿改）
  软限位: ±190°
==============================================================================*)
IF GVL.Error_code <> 0 THEN
	bVisError := TRUE;
ELSE
	bVisError := FALSE;
END_IF

(* 远控参量注释块为历史 Az 轴拷贝，倾斜轴参数由 Modbus_Slave 写入 Axis3Remote *)

// =============================================================================
// 段 1: 驱动状态 → Axis3Status
// =============================================================================
Axis3Status.Error := GVL.bTiStsBit3;
Axis3Status.ErrorID := GVL.eTiErrorcode;
Axis3Status.bServo_Enable := GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2;
Axis3Status.bBrake := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Status.Disabled := NOT (GVL.bTiStsBit0 AND GVL.bTiStsBit1 AND GVL.bTiStsBit2);
Axis3Remote.rSoft_limit_Negative:=-190;Axis3Remote.rSoft_limit_Postive:=190;
Axis3Local.rSoft_limit_Negative:=-190;Axis3Local.rSoft_limit_Postive:=190;

// =============================================================================
// 段 2: CANopen 反馈 → rFctVelReal_3 / rFctPosReal_3
// =============================================================================
rFctVelReal_3:=DINT_TO_REAL(diTiActVel)/524288.0*360.0;
rFctPosReal_3:=DINT_TO_REAL(diTiActPos)/524288.0*360.0;

// =============================================================================
// 段 3: rPosCmd 硬限位 ±190°
// 注意: 上限分支写的是 Axis2Local（原代码），与 Axis3Local 不一致，保持不改
// =============================================================================
Axis3Limit_pos:=190;
Axis3Limit_Neg:=-190;
IF Axis3Remote.rPosCmd>Axis3Limit_pos THEN
	Axis3Remote.rPosCmd:=190;
ELSIF Axis3Remote.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Remote.rPosCmd:=-190;  
END_IF

IF Axis3Local.rPosCmd>Axis3Limit_pos THEN
	Axis2Local.rPosCmd:=190;
ELSIF Axis3Local.rPosCmd<Axis3Limit_Neg THEN
	 Axis3Local.rPosCmd:=-190;  
END_IF

// =============================================================================
// 段 4: 停稳判定 → Axis3Status.Moving
// =============================================================================
IF  ABS(rFctVelReal_3)<0.035 THEN
	Stop3_Count:=Stop3_Count+1;
	IF Stop3_Count>100 THEN
		Stop3_Count:=101;
		bStop_3:=TRUE;;
	END_IF
ELSE
	Stop3_Count:=0;
	bStop_3:=FALSE;
END_IF
Axis3Status.Moving := NOT bStop_3;

// =============================================================================
// 段 5: PID 使能（mode 2 / 4）
// =============================================================================
IF Axis3Remote.iMode=2 OR Axis3Remote.iMode=4 THEN
	Axis3Remote.bPIDEnable:=TRUE;
ELSE
	Axis3Remote.bPIDEnable:=FALSE;
END_IF

// =============================================================================
// 段 6: 远控 ↔ 本控 切换保护
// 远→本: 仅 Axis3Remote.iMode:=7（与 El/Az 双轴同步 halt 不同）
// =============================================================================
bRTriger(CLK:=GVL.bLocalCtrl);
bFTriger(CLK:=GVL.bLocalCtrl);

IF Axis3Status.bServo_Enable AND (bRTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bRemote2LocalStop:=TRUE;
END_IF
IF bRemote2LocalStop  THEN //若减速停止标识符为True 

	IF  bStop_3=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis3Local.iMode:=0;
		Axis3Remote.iMode:=0;
		IF Axis3Status.bServo_Enable=FALSE THEN
			bRemote2LocalStop:=FALSE;
		END_IF
	ELSE
		Axis3Remote.iMode:=7;
	END_IF
END_IF

IF Axis3Status.bServo_Enable AND (bFTriger.Q ) THEN//如果速度不为0且本控发生切换，则减速停止标识为True
	bLocal2RemoteStop:=TRUE;
END_IF
IF bLocal2RemoteStop  THEN //若减速停止标识符为True 

	IF  bStop_3=TRUE THEN//且电机速度不为0 开始减速 减速完成后下使能，下使能完成后复位标识符复位
		Axis3Local.iMode:=0;
		Axis3Remote.iMode:=0;
		IF Axis3Status.bServo_Enable=FALSE THEN
			bLocal2RemoteStop:=FALSE;
		END_IF
	ELSE
		Axis3Remote.iMode:=7;
		Axis3Local.iMode:=7;
	END_IF
END_IF

(* 自跟踪与 rPIDCmdPos 程引合成在此轴已注释，当前仅对既有 rPIDCmdPos 做限位 *)

// =============================================================================
// 段 7: rPIDCmdPos 限位（赋值在其他 POU，如 Modbus_Slave / RealTimePosCal）
// =============================================================================
IF Axis3Remote.rPIDCmdPos<-190 THEN
	Axis3Remote.rPIDCmdPos:=-190;
ELSIF Axis3Remote.rPIDCmdPos>190 THEN
	Axis3Remote.rPIDCmdPos:=190;
END_IF

Axis3_Ctrl(sLocal:=Axis3Local, sCtrl:=Axis3Remote, sStatus:=Axis3Status, sVisible:=Axis3Visible, rRealPos:=rFctPosReal_3, rPosLimK:=0.34);

(*==============================================================================
  FB: Ti_Ctrl_FB（倾斜轴 Tilt 控制功能块）
  与 El_Ctrl_FB / Az_Ctrl_FB 结构基本相同，主要差异:
    - 操作的 GVL 变量为 Ti 系列（diTiTargetVel / bTiCtrlBitX / eTiErrorcode 等）
    - 无 vpid1（Ti 轴不做变增益，programBootMode 远控直接用 VelPID_1）
    - positionMode 加速度为 10 deg/s²
    - positionMode bStartAutoTrack 分支注释掉（Ti 无自跟踪需求）
    - programBootMode 本控用 VelPID_2，参数直接来自 sLocal.rP/rI/rD
    - programBootMode 远控 bStartAutoTrack=TRUE 时调用 VelPID_1（非 vpid1）

  速度换算公式（通用）:
    diTiTargetVel [inc/s] = deg/s × 524288 / 360
==============================================================================*)

// =============================================================================
// 段 A: 轴停止或下电时清快速停止位 bit8
// =============================================================================
IF sStatus.Disabled OR(NOT sStatus.Moving)THEN
	bTiCtrlBit8 := FALSE;
END_IF

// =============================================================================
// 段 B: 全局错误复位
// =============================================================================
IF GVL.bError_Reset THEN
	sCtrl.iMode:=6;
	sLocal.iMode:=6;
	GVL.Error_code:=0;
END_IF
IF GVL.Error_code =0 THEN
	GVL.bError_Reset:=FALSE;
END_IF

// =============================================================================
// 段 C: CANopen 心跳超时（0x8130）自动恢复序列
// =============================================================================
IF GVL.eTiErrorcode = 16#8130 AND NOT tr THEN
	GVL.bTiCtrlBit7 := TRUE;
	tr:=TRUE;
	istate:=0;
	icount:=0;
	// 写入下电控制字
	GVL.bTiCtrlBit3 := FALSE;
	GVL.bTiCtrlBit0 := FALSE;
	GVL.bTiCtrlBit1 := FALSE;
	GVL.bTiCtrlBit2 := FALSE;
END_IF
IF tr THEN
	icount1 := icount1 + 1;
END_IF
IF icount1 > 101 THEN
	icount1 := 0;
	tr := FALSE;
	GVL.bTiCtrlBit7 := FALSE;
	bfin1 := TRUE;
END_IF
IF bfin1 THEN
	icount2 := icount2 + 1;
END_IF
IF icount2 > 101 THEN
	bfin1 := FALSE;
	icount2 := 0;
END_IF

// =============================================================================
// 段 D: 主控制逻辑
// =============================================================================
IF GVL.Error_code=0 AND GVL.eTiErrorcode = 0 AND NOT GVL.bTiCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN

	// =========== 远控 ===========
	IF GVL.bLocalCtrl=FALSE THEN //远控
		IF sCtrl.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sCtrl.iMode OF

			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bTiCtrlBit3 := FALSE;
						GVL.bTiCtrlBit0 := FALSE;
						GVL.bTiCtrlBit1 := FALSE;
						GVL.bTiCtrlBit2 := FALSE;
					END_IF
				END_IF

			MODES.powerOn:  // 上电（DS402 三步序列）
				IF sStatus.Disabled THEN
					GVL.diTiTargetVel := 0;
					IF GVL.siTiMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siTiMode := 3;
					END_IF
					IF siTiMode = 3 THEN
						CASE istate OF
							0:
								GVL.bTiCtrlBit1 := TRUE;
								GVL.bTiCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bTiCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bTiCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.positionMode: // 远控指向模式（加速度 10 deg/s²，Kp=0.8）
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						// Ti 轴自跟踪分支已注释掉，实际走 ELSE
						(*
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);
*)							
					ELSE
						//PID计算速度指令
						VelPID_1(rTarget:=sCtrl.rPosCmd,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.Pos_Vel,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=0.8,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=0,
							rKd:=0,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(10 * 524288 / 360);   //加速度 10 deg/s²
					GVL.diTiTargetDec := REAL_TO_UDINT(10 * 524288 / 360);   //减速度
				END_IF

			MODES.velocityMode://手控速度模式-远控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sCtrl.rVelCmd) <= sCtrl.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rVelCmd * 524288 / 360);
					ELSIF sCtrl.rVelCmd > sCtrl.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diTiTargetVel := REAL_TO_DINT(-sCtrl.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diTiTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.programBootMode://PID速度模式-正常模式 程引（Ti 轴用 VelPID_1，非 vpid）
				IF NOT sStatus.Disabled THEN
					IF sCtrl.bStartAutoTrack THEN
						// 程引+自跟踪：误差电压叠加到插值位置
						VelPID_1(rTarget:=sCtrl.rChanU + rRealPos,
								rFeedback:=rRealPos,
								rPosLimPositive:=sCtrl.rSoft_limit_Postive,
								rPosLimNegative:=sCtrl.rSoft_limit_Negative,
								rVelLim:=sCtrl.rVel_Limit,
								rKp:=sCtrl.rP_AutoTrack,//自跟踪PI系数3,0.02
								rKi:=sCtrl.rI_AutoTrack,
								rKd:=sCtrl.rD,
								bPIDEnable:=sCtrl.bPIDEnable,
								iThreshold:= -1,
								rPIDOutput=>sCtrl.rPIDCmdVel);							
					ELSE
						//PID计算速度指令（参数来自 sCtrl.rP/rI/rD，由 Modbus/上位机配置）
						VelPID_1(rTarget:=sCtrl.rPIDCmdPos,
							rFeedback:=rRealPos,
							rVelLim:=sCtrl.rVel_Limit,
							rPosLimPositive:=sCtrl.rSoft_limit_Postive,
							rPosLimNegative:=sCtrl.rSoft_limit_Negative,
							rKp:=sCtrl.rP,//程引PI系数地带：1,0.002  高带：3,0.02
							rKi:=sCtrl.rI,
							rKd:=sCtrl.rD,
							bPIDEnable:=sCtrl.bPIDEnable,
							iThreshold:=sCtrl.rPIDThre,
							rPIDOutput=>sCtrl.rPIDCmdVel);
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sCtrl.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(sCtrl.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sCtrl.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.reset://重置
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE

	// =========== 本控 ===========
	ELSE // 本控
		IF sLocal.iMode <> 1 THEN
			istate:=0;
			icount:=0;
		END_IF
		CASE sLocal.iMode OF

			MODES.powerOff: // 下电
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN // 运动中，先停止运动
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						// 写入下电控制字
						GVL.bTiCtrlBit3 := FALSE;
						GVL.bTiCtrlBit0 := FALSE;
						GVL.bTiCtrlBit1 := FALSE;
						GVL.bTiCtrlBit2 := FALSE;
					END_IF
				END_IF

			MODES.powerOn:  // 上电
				IF sStatus.Disabled THEN
					GVL.diTiTargetVel := 0;
					IF GVL.siTiMode <> 3 THEN // 上电时模式默认为3，速度模式
						GVL.siTiMode := 3;
					END_IF
					IF siTiMode = 3 THEN
						CASE istate OF
							0:
								GVL.bTiCtrlBit1 := TRUE;
								GVL.bTiCtrlBit2 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=1;
								END_IF
							1:
								GVL.bTiCtrlBit0 := TRUE;
								icount := icount + 1;
								IF icount = 20 THEN
									icount:=0;
									istate:=2;
								END_IF
							2:
								GVL.bTiCtrlBit3 := TRUE;
						END_CASE
					END_IF
				ELSE
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

			MODES.velocityMode://手控速度模式-本控模式
				IF NOT sStatus.Disabled THEN
					IF ABS(sLocal.rVelCmd) <= sLocal.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rVelCmd * 524288 / 360);
					ELSIF sLocal.rVelCmd > sLocal.rVel_Limit THEN
						GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rVel_Limit * 524288 / 360);
					ELSE
						GVL.diTiTargetVel := REAL_TO_DINT(-sLocal.rVel_Limit * 524288 / 360);
					END_IF
					GVL.diTiTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.programBootMode://本控位置模式（普通 PID，参数来自 sLocal.rP/rI/rD）
				IF NOT sStatus.Disabled THEN
					IF NOT sLocal.bPIDEnable THEN
						GVL.diTiTargetVel := 0;							
					ELSE
						//PID计算速度指令
						 VelPID_2(rTarget:=sLocal.rPosCmd,
							     rFeedback:=rRealPos,
								 rPosLimPositive:=sLocal.rSoft_limit_Postive,//软限位
								 rPosLimNegative:=sLocal.rSoft_limit_Negative,
								 rKp:=sLocal.rP,
								 rKi:=sLocal.rI,
								 rKd:=sLocal.rD,
								 iThreshold:=sLocal.rPIDThre,
								 bPIDEnable:=sLocal.bPIDEnable,
								 rVelLim:=sLocal.Pos_Vel,
								 rPIDOutput=>sLocal.rPIDCmdVel);//普通PID
					END_IF
					GVL.diTiTargetVel := REAL_TO_DINT(sLocal.rPIDCmdVel * 524288 / 360);
					GVL.diTiTargetAcc := REAL_TO_UDINT(sLocal.rAcceleration * 524288 / 360);   //加速度
					GVL.diTiTargetDec := REAL_TO_UDINT(sLocal.rDeceleration * 524288 / 360);   //减速度
				END_IF

			MODES.reset://重置
			// 是否需要
			MODES.halt://待机
				IF NOT sStatus.Disabled THEN
					IF sStatus.Moving THEN
						GVL.diTiTargetVel := 0;
						bTiCtrlBit8 := TRUE;
					ELSE
						bTiCtrlBit8 := FALSE;
					END_IF
				END_IF

		END_CASE
	END_IF

// =============================================================================
// 段 E: 全局错误时强制停轴，超时后强制下电
// =============================================================================
ELSIF GVL.Error_code<>0 AND GVL.eTiErrorcode = 0 AND NOT GVL.bTiCtrlBit7  AND NOT tr AND NOT bfin1 AND NOT bfin2 THEN
	// 出现错误，轴停止运动
	GVL.diTiTargetVel := 0;
	bTiCtrlBit8 := TRUE;
	TON_0(IN:=bTiCtrlBit8,PT:=T#1S,Q=>,ET=>);//判断stop0执行是否超时,若超时强制下电（手动复位）
	IF TON_0.Q THEN
		bTick:=TRUE;
	END_IF
	IF bTick AND sStatus.Moving THEN // 超时强制下电
		// 写入下电控制字
		GVL.bTiCtrlBit3 := FALSE;
		GVL.bTiCtrlBit0 := FALSE;
		GVL.bTiCtrlBit1 := FALSE;
		GVL.bTiCtrlBit2 := FALSE;
	END_IF
END_IF

(*==============================================================================
  FB: vpid（变增益自适应 PID）
  任务: Canopen 10ms（由 El_Ctrl_FB / Az_Ctrl_FB 在 programBootMode 下调用）
  作用: 与 PID 相似，但 Kp/Ki 根据当前俯仰角（rElPos）动态调整
        俯仰角越大（天线仰角越高），摩擦力和惯量变化大，需更高增益
  与 PID 的区别:
    - 输入参数带 Kp/Ki 基础值、缩放因子、最大值
    - 内部按 rElPos > rVelThreshold 时线性增加 Kp/Ki
    - 输出走 rPIDOutDir（方向输出）而非 rPIDOutput
  来源参数: PersistentVars.rXxKpBase/rXxKiBase 等（掉电保持，可由 HMI/Modbus 标定）
==============================================================================*)

// ----- 段：PID 使能入口 -----
IF (bPIDEnable) THEN // 如果PID使能
    IF rTarget = rFeedback THEN
        rPIDOutDir := 0;    
    ELSE
        rErrorNow := rTarget - rFeedback; // 计算当前误差
        rProportionNew := rErrorNow;      // 比例项

		// ----- 段：根据俯仰角动态计算目标 Kp/Ki -----
		// rElPos = 当前俯仰角 - 90，即相对水平的仰角
		// 当仰角 > rVelThreshold 时，增益线性增加
		IF rElPos > rVelThreshold THEN
			rKpTarget := rKpBase + rKpScale * (rElPos - rVelThreshold);
			rKiTarget := rKiBase + rKiScale * (rElPos - rVelThreshold);
		ELSE
			rKpTarget := rKpBase;
			rKiTarget := rKiBase;
		END_IF
        // ----- 段：Kp/Ki 上限保护 -----
        IF rKpTarget > rKpMax THEN
			rKpTarget := rKpMax;
		END_IF
		IF rKiTarget > rKiMax THEN
			rKiTarget := rKiMax;
		END_IF

		// ----- 段：Kp/Ki 平滑追踪目标值（rStep 步进，防增益突变抖动）-----
		IF rKp<=rKpTarget THEN
			rKp:=rKp+rStep;
		ELSE
			rKp:=rKp-rStep;
		END_IF
		IF rKi<=rKiTarget THEN
			rKi:=rKi+(rKiScale/rKpScale)*rStep;
		ELSE
			rKi:=rKi-(rKiScale/rKpScale)*rStep;
		END_IF
	END_IF

        // ----- 段：条件积分（与 PID 相同逻辑）-----
        IF rFeedback > rPosLimNegitive AND rFeedback < rPosLimPositive THEN // 若在软限位之内，工作时开启积分项
            IF (ABS(rTarget - rFeedback) < iThrehold) THEN // 位置差小于积分阈值
                rIntegralNew := rIntegralNew + rErrorNow;  // 积分项
            ELSE
                rIntegralNew := rIntegralNew;  // 积分项
            END_IF;
        ELSE // 不在软限位范围内，则积分项为0
            rIntegralNew := 0;
        END_IF
        (*
        // 防止目标位置与当前位置偏差过大，导致比例项输出太大，引起震动
        IF rKp * rProportionNew > 2 THEN
            rPIDOutput := 2;
        ELSIF rKp * rProportionNew < -2 THEN
            rPIDOutput := -2;
        ELSE
            rPIDOutput := rKp * rProportionNew + rKi * rIntegralNew / 1000.0; // 由于需求积分项过小，因此积分系数在接口数据上除1000
        END_IF
        *)
		rPIDOutput := rKp * rProportionNew + rKi * rIntegralNew; // 由于需求积分项过小，因此积分系数在接口数据上除1000
        // 根据方向设置输出
        IF rPIDOutput < 0 THEN
            rPIDOutDir := rPIDOutput;
        ELSE
            rPIDOutDir := rPIDOutput;
        END_IF

        // ----- 段：速度限幅 -----
        IF (ABS(rPIDOutDir) > rVelLim) THEN
            IF rPIDOutDir < (-rVelLim) THEN
                rPIDOutDir := -rVelLim;
            ELSIF rPIDOutDir > rVelLim THEN
                rPIDOutDir := rVelLim;
            END_IF
        END_IF

        // ----- 段：超软限位时强制输出清零 -----
        IF rFeedback > rPosLimPositive AND rPIDOutDir > 0  THEN
            rPIDOutDir := 0;
        END_IF
        IF rFeedback < rPosLimNegitive AND rPIDOutDir <= 0 THEN
            rPIDOutDir := 0;
        END_IF

        //rLastFeedback := rFeedback; // 将当前反馈值赋值给上一次反馈值
		//rInterValueLast := rInterValueNow; // 将当前插值位置值赋值给上一次

ELSE // 非使能清零PID各项
    rProportionNew := 0.0;
    rIntegralNew := 0.0;
    rPIDOutDir := 0.0;
    rPIDOutput := 0.0;
END_IF

(*==============================================================================
  PRG: READ_485（跟踪接收机 RS485 通信）
  任务: SerialCom 5ms（与 GPRMC_1 同任务，端口不同）
  硬件: GCAN 串口 mPort=2（485），19200 8N1
  作用:
    - 读跟踪接收机上报帧 → 解析 AGC、Ua、Ue、锁定、Eb/N0
    - 写入 GVL.Chan1AGC / Chan1Ua / Chan1Ue / Chan1Lock
    - 输出 Chan1EB_N0、recBuf[1]、bEBN0Lock 供 SecurityCheck / 捕获扫描
  帧布局（当前简化协议，非 0x7E 定界）:
    recBuf[1]     — 锁定标志 (1=锁定)
    recBuf[2..3]  — AGC 原始 WORD
    recBuf[4..5]  — 方位误差 Ua 原始 INT
    recBuf[6..7]  — 俯仰误差 Ue 原始 INT
    recBuf[8..15] — Eb/N0 用两路 DWORD 算信噪比
==============================================================================*)

mPort:=2;								//串口端口号设定

// ----- 首次上电：485 初始化 19200 -----
IF isFirst THEN
	com_init(
	EN_IN:=TRUE,
	xEnable:=TRUE,
	bPort:=mPort,
	uiBaudrate:=19200,
	bParity:=0,
	bDatabits:=8,
	bStopbits:=1,
	EN_OUT=>m_out,
	uiError=>m_uiError);
	isfirst:=FALSE;

ELSE
	com_read(
	EN_in:=TRUE,
	bPort:=mPort,
	p_brxdata:=ADR(recBuf),
	uiMaxsize:=20,
	EN_out=>m_out,
	uiRecSize=>recSize,
	uierror=>m_uierror);

	// ----- 段 1: 锁定标志 → GVL.Chan1Lock -----
	//GVL.Chan1Lock := BYTE_TO_BOOL(recBuf[1]);
	IF recBuf[1] = 1 AND GVL.Chan1AGC >= GVL.Chanthreshold THEN
		GVL.Chan1Lock := TRUE;
	ELSE
		GVL.Chan1Lock := FALSE;
	END_IF

	// ----- 段 2: 按字节拼接 WORD/INT（Word2Bit UNION）-----
	Word2Bit1.Apart_Byte[1] := recBuf[2];
	Word2Bit1.Apart_Byte[2] := recBuf[3];
	wAGC:=Word2Bit1.Apart_Word;

	Word2Bit2.Apart_Byte[1] := recBuf[4];
	Word2Bit2.Apart_Byte[2] := recBuf[5];
	iUa:=Word2Bit2.Apart_INT;

	Word2Bit3.Apart_Byte[1] := recBuf[6];
	Word2Bit3.Apart_Byte[2] := recBuf[7];
	iUe:=Word2Bit3.Apart_INT;

	// ----- 段 3: 换算为物理量并限幅后写 GVL -----
	// Ua/Ue: ±5V 满量程对应 INT±2048；AGC: 5 - (raw×5/76) 越大信号越强
	IF ABS(INT_TO_REAL(iUa) * 5 / 2048) <= 5 AND ABS(INT_TO_REAL(iUe) * 5 / 2048) <= 5 AND ABS((WORD_TO_REAL(wAGC) * 5 / 76)) <=5 THEN
		GVL.Chan1Ua := INT_TO_REAL(iUa) * 5 / 2048;
		GVL.Chan1Ue := INT_TO_REAL(iUe) * 5 / 2048;
		GVL.Chan1AGC := 5 - (WORD_TO_REAL(wAGC) * 5 / 76);
	END_IF

	// ----- 段 4: Eb/N0 估算（两 DWORD，字节序见 Dword2Bit 填入顺序）-----
	Dword2Bit1.Apart_Byte[3] := recBuf[8];
	Dword2Bit1.Apart_Byte[4] := recBuf[9];
	Dword2Bit1.Apart_Byte[1] := recBuf[10];
	Dword2Bit1.Apart_Byte[2] := recBuf[11];	

	Dword2Bit2.Apart_Byte[3] := recBuf[12];
	Dword2Bit2.Apart_Byte[4] := recBuf[13];
	Dword2Bit2.Apart_Byte[1] := recBuf[14];
	Dword2Bit2.Apart_Byte[2] := recBuf[15];	

	rQData:=DWORD_TO_REAL(Dword2Bit2.Apart_DWORD);
	rSData:=DWORD_TO_REAL(Dword2Bit1.Apart_DWORD)-rQData;

	IF rSData<>0  AND rQData<>0  THEN
		Chan1EB_N0 := 10*LOG(ABS(rSData/rQData))+3.8;
	ELSE
		Chan1EB_N0 := 0;
	END_IF

	// ----- 段 5: bEBN0Lock — 程引/指向且 Eb/N0≥29 或 ACU 请求自跟踪 -----
	IF ((GVL.Axis1Remote.iMode = 2 OR GVL.Axis1Remote.iMode = 4) AND Chan1EB_N0 >= 29)AND READ_485.recBuf[1] = 1 OR Modbus_Slave.bStartTrackAcu THEN
		icount0:=0;
		bEBN0Lock := TRUE;
	END_IF
	// 锁定字节为 0 时累计；超 400 拍或下电则清 bEBN0Lock
	IF ( GVL.Axis1Remote.iMode = 4 or GVL.Axis1Remote.iMode =2 ) AND recBuf[1] = 0 THEN
		icount0:=icount0+1;
	END_IF
	IF icount0 > 400 OR (GVL.Axis1Remote.iMode = 0 OR GVL.Axis1Remote.iMode = 0) THEN
		icount0 := 401;
		bEBN0Lock := FALSE;
	END_IF
END_IF

(* 旧版 0x7E 定界帧解析整段已注释 *)

rRealTime := uliRealTime / 1000.0 - lrStartTime/1000.0;


IF rRealTime <= 0.0 THEN
	rDelTime := 0.0;
	lrFitResult := lrFun1[10];
ELSIF rRealTime <= rNodeTime1 THEN
    rDelTime := rRealTime - 0.0;
	lrFitResult := lrFun1[0] * EXPT(rDelTime,10) + lrFun1[1] * EXPT(rDelTime,9) + lrFun1[2] * EXPT(rDelTime,8) + lrFun1[3] * EXPT(rDelTime,7) + lrFun1[4] * EXPT(rDelTime,6) + lrFun1[5] * EXPT(rDelTime,5)
    + lrFun1[6] * EXPT(rDelTime,4) + lrFun1[7] * EXPT(rDelTime,3) + lrFun1[8] * EXPT(rDelTime,2) + lrFun1[9] * rDelTime + lrFun1[10];
ELSIF rRealTime <= rNodeTime2 THEN
    rDelTime := rRealTime - rNodeTime1;
    lrFitResult := lrFun2[0] * EXPT(rDelTime,10) + lrFun2[1] * EXPT(rDelTime,9) + lrFun2[2] * EXPT(rDelTime,8) + lrFun2[3] * EXPT(rDelTime,7) + lrFun2[4] * EXPT(rDelTime,6) + lrFun2[5] * EXPT(rDelTime,5)
    + lrFun2[6] * EXPT(rDelTime,4) + lrFun2[7] * EXPT(rDelTime,3) + lrFun2[8] * EXPT(rDelTime,2) + lrFun2[9] * rDelTime + lrFun2[10];
ELSIF rRealTime <= rNodeTime3 THEN
    rDelTime := rRealTime - rNodeTime2;
    lrFitResult := lrFun3[0] * EXPT(rDelTime,10) + lrFun3[1] * EXPT(rDelTime,9) + lrFun3[2] * EXPT(rDelTime,8) + lrFun3[3] * EXPT(rDelTime,7) + lrFun3[4] * EXPT(rDelTime,6) + lrFun3[5] * EXPT(rDelTime,5)
    + lrFun3[6] * EXPT(rDelTime,4) + lrFun3[7] * EXPT(rDelTime,3) + lrFun3[8] * EXPT(rDelTime,2) + lrFun3[9] * rDelTime + lrFun3[10];
ELSIF rRealTime <= rNodeTime4 THEN
    rDelTime := rRealTime - rNodeTime3;
    lrFitResult := lrFun4[0] * EXPT(rDelTime,10) + lrFun4[1] * EXPT(rDelTime,9) + lrFun4[2] * EXPT(rDelTime,8) + lrFun4[3] * EXPT(rDelTime,7) + lrFun4[4] * EXPT(rDelTime,6) + lrFun4[5] * EXPT(rDelTime,5)
    + lrFun4[6] * EXPT(rDelTime,4) + lrFun4[7] * EXPT(rDelTime,3) + lrFun4[8] * EXPT(rDelTime,2) + lrFun4[9] * rDelTime + lrFun4[10];
ELSIF rRealTime <= rNodeTime5 THEN
    rDelTime := rRealTime - rNodeTime4;
    lrFitResult := lrFun5[0] * EXPT(rDelTime,10) + lrFun5[1] * EXPT(rDelTime,9) + lrFun5[2] * EXPT(rDelTime,8) + lrFun5[3] * EXPT(rDelTime,7) + lrFun5[4] * EXPT(rDelTime,6) + lrFun5[5] * EXPT(rDelTime,5)
    + lrFun5[6] * EXPT(rDelTime,4) + lrFun5[7] * EXPT(rDelTime,3) + lrFun5[8] * EXPT(rDelTime,2) + lrFun5[9] * rDelTime + lrFun5[10];
ELSIF rRealTime <= rEndTime THEN
    rDelTime := rRealTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
ELSE
    rDelTime := rEndTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
END_IF

IF lrFitResult>270 THEN
	lrFitResult:=270;
ELSIF lrFitResult<-270 THEN
	lrFitResult:=-270;
END_IF

rRealTime := uliRealTime / 1000.0 - lrStartTime/1000.0;


IF rRealTime <= 0.0 THEN
	rDelTime := 0.0;
	lrFitResult := lrFun1[10];
ELSIF rRealTime <= rNodeTime1 THEN
    rDelTime := rRealTime - 0.0;
	lrFitResult := lrFun1[0] * EXPT(rDelTime,10) + lrFun1[1] * EXPT(rDelTime,9) + lrFun1[2] * EXPT(rDelTime,8) + lrFun1[3] * EXPT(rDelTime,7) + lrFun1[4] * EXPT(rDelTime,6) + lrFun1[5] * EXPT(rDelTime,5)
    + lrFun1[6] * EXPT(rDelTime,4) + lrFun1[7] * EXPT(rDelTime,3) + lrFun1[8] * EXPT(rDelTime,2) + lrFun1[9] * rDelTime + lrFun1[10];
ELSIF rRealTime <= rNodeTime2 THEN
    rDelTime := rRealTime - rNodeTime1;
    lrFitResult := lrFun2[0] * EXPT(rDelTime,10) + lrFun2[1] * EXPT(rDelTime,9) + lrFun2[2] * EXPT(rDelTime,8) + lrFun2[3] * EXPT(rDelTime,7) + lrFun2[4] * EXPT(rDelTime,6) + lrFun2[5] * EXPT(rDelTime,5)
    + lrFun2[6] * EXPT(rDelTime,4) + lrFun2[7] * EXPT(rDelTime,3) + lrFun2[8] * EXPT(rDelTime,2) + lrFun2[9] * rDelTime + lrFun2[10];
ELSIF rRealTime <= rNodeTime3 THEN
    rDelTime := rRealTime - rNodeTime2;
    lrFitResult := lrFun3[0] * EXPT(rDelTime,10) + lrFun3[1] * EXPT(rDelTime,9) + lrFun3[2] * EXPT(rDelTime,8) + lrFun3[3] * EXPT(rDelTime,7) + lrFun3[4] * EXPT(rDelTime,6) + lrFun3[5] * EXPT(rDelTime,5)
    + lrFun3[6] * EXPT(rDelTime,4) + lrFun3[7] * EXPT(rDelTime,3) + lrFun3[8] * EXPT(rDelTime,2) + lrFun3[9] * rDelTime + lrFun3[10];
ELSIF rRealTime <= rNodeTime4 THEN
    rDelTime := rRealTime - rNodeTime3;
    lrFitResult := lrFun4[0] * EXPT(rDelTime,10) + lrFun4[1] * EXPT(rDelTime,9) + lrFun4[2] * EXPT(rDelTime,8) + lrFun4[3] * EXPT(rDelTime,7) + lrFun4[4] * EXPT(rDelTime,6) + lrFun4[5] * EXPT(rDelTime,5)
    + lrFun4[6] * EXPT(rDelTime,4) + lrFun4[7] * EXPT(rDelTime,3) + lrFun4[8] * EXPT(rDelTime,2) + lrFun4[9] * rDelTime + lrFun4[10];
ELSIF rRealTime <= rNodeTime5 THEN
    rDelTime := rRealTime - rNodeTime4;
    lrFitResult := lrFun5[0] * EXPT(rDelTime,10) + lrFun5[1] * EXPT(rDelTime,9) + lrFun5[2] * EXPT(rDelTime,8) + lrFun5[3] * EXPT(rDelTime,7) + lrFun5[4] * EXPT(rDelTime,6) + lrFun5[5] * EXPT(rDelTime,5)
    + lrFun5[6] * EXPT(rDelTime,4) + lrFun5[7] * EXPT(rDelTime,3) + lrFun5[8] * EXPT(rDelTime,2) + lrFun5[9] * rDelTime + lrFun5[10];
ELSIF rRealTime <= rEndTime THEN
    rDelTime := rRealTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
ELSE
    rDelTime := rEndTime - rNodeTime5;
    lrFitResult := lrFun6[0] * EXPT(rDelTime,10) + lrFun6[1] * EXPT(rDelTime,9) + lrFun6[2] * EXPT(rDelTime,8) + lrFun6[3] * EXPT(rDelTime,7) + lrFun6[4] * EXPT(rDelTime,6) + lrFun6[5] * EXPT(rDelTime,5)
    + lrFun6[6] * EXPT(rDelTime,4) + lrFun6[7] * EXPT(rDelTime,3) + lrFun6[8] * EXPT(rDelTime,2) + lrFun6[9] * rDelTime + lrFun6[10];
END_IF

IF lrFitResult>90 THEN
	lrFitResult:=90;
ELSIF lrFitResult<3 THEN
	lrFitResult:=3;
END_IF

(*==============================================================================
  FB: AGCMaxSearch_PB_1（AGC 峰值搜索：单轴拉偏搜索）
  调用者: `Az_ctrl_1` / `El_ctrl_1`
  目标: 在指向(mode2)或程引(mode4)时，沿单轴正/负方向试探移动 rStepBias，
        找到使 AGC 最大的位置偏置 rAGCMaxBias，并在到位稳定后置 bSucess

  关键变量含义:
    rStepBias      — 当前偏置输出（逐步累加 rDirection*rStep）
    rAGCMaxBias    — 历史最大 AGC 对应的偏置
    rAGCInit       — 启动时 AGC 基线
    rSensitivity   — 判定“AGC 明显下降/上升”的阈值，用于决定停止/换向
    iCountDirChange— 换向次数；=2 后进入“回到峰值位置并等待稳定”阶段

  完成判定:
    - 偏置回到 rAGCMaxBias 后，(rInterPos+rStepBias) 与 rCurrentPos 误差持续小于 0.002
    - 持续计数超过 iCountBlockEndMax 后，再用 TON(1s) 确认稳定 → bSucess=TRUE
==============================================================================*)

rTrg(CLK:=bstart,Q=>);

IF rTrg.Q THEN
	rAGCInit:=rAGCNow;
	rAGCMaxValue:=rAGCNow;
	//rBiasInit:=rCurrentPos-rInterPos;//获取启动时的拉偏量
END_IF

IF bstart THEN
	//搜索换向两次
	IF iCountDirChange=2 THEN
		rSearchNextStepTarget:=rAGCMaxBias;
		IF rStepBias< rSearchNextStepTarget THEN 
			rStepBias:=rStepBias+rStep;
		ELSIF rStepBias> rSearchNextStepTarget THEN
			rStepBias:=rStepBias-rStep;
		ELSE
			rStepBias:=rStepBias;
		END_IF

		IF ABS((rInterPos+rStepBias)-rCurrentPos)<0.002 THEN //若位置达到最强位置，则输出成功 //可能只是路过这里,需要持续
			//需要判断稳定
			iCountBlockEnd:=iCountBlockEnd+1;
		ELSE
			iCountBlockEnd:=0;
		END_IF
		IF iCountBlockEnd>iCountBlockEndMax THEN
			iCountBlockEnd:=iCountBlockEndMax+1;
			//用TON1秒后触发
			ton(IN:=TRUE,PT:=T#1S,Q=>,ET=>);
		END_IF
		IF ton.Q THEN
			bSucess:=TRUE;
		END_IF
	ELSE
		rStepBias:=rStepBias+rDirection*rStep;
		IF rDirection<0 THEN
			//若是向小走
			IF rCurrentPos<rInterPos THEN
				IF rAGCNow<rAGCMaxValue-rSensitivity THEN
					iCountStop1:=iCountStop1+1;
					IF iCountStop1>iCountStopMax THEN
						iCountStop1:=iCountStopMax+1;
						IF bSearchRight THEN
							iCountDirChange:=2;
						ELSE
							iCountDirChange:=iCountDirChange+1;
						END_IF
						rDirection:=rDirection*(-1);
					END_IF
				ELSE
					iCountStop1:=0;	
				END_IF

				//新加的 测试第一阶段搜索正确后不进行第二次搜索
				IF rAGCNow>rAGCInit+rSensitivity THEN
					iCountSearchRight:=iCountSearchRight+1;
				ELSE
					iCountSearchRight:=0;
				END_IF
				IF iCountSearchRight>200 THEN
					iCountSearchRight:=201;
					bSearchRight:=TRUE;
				END_IF

			END_IF
		ELSE
			//若是向正走
			IF rCurrentPos>rInterPos THEN
				IF rAGCNow<rAGCMaxValue-rSensitivity THEN
					iCountStop2:=iCountStop2+1;
					IF iCountStop2>iCountStopMax THEN
						iCountStop2:=iCountStopMax+1;
						IF bSearchRight THEN
							iCountDirChange:=2;
						ELSE
							iCountDirChange:=iCountDirChange+1;
						END_IF
						rDirection:=rDirection*(-1);
					END_IF
				ELSE
					iCountStop2:=0;	
				END_IF

				//新加的
				IF rAGCNow>rAGCInit+rSensitivity THEN
					iCountSearchRight:=iCountSearchRight+1;
				ELSE
					iCountSearchRight:=0;
				END_IF
				IF iCountSearchRight>200 THEN
					iCountSearchRight:=201;
					bSearchRight:=TRUE;
				END_IF

			END_IF
		END_IF
		(*
		IF rAGCNow<rAGCInit-0.05 THEN
			iCountStop1:=iCountStop1+1;
			IF iCountStop1>150 THEN
				iCountDirChange:=iCountDirChange+1;
				rDirection:=rDirection*(-1);
			END_IF
		ELSE
			iCountStop1:=0;	
		END_IF
		*)

		 // 记录最强信号的拉偏量和值
		//IF rAGCNow >= rAGCInit AND rAGCNow> rAGCMaxValue THEN
		IF  rAGCNow> rAGCMaxValue THEN
			rAGCMaxBias := rStepBias;
			rAGCMaxValue := rAGCNow;
		END_IF
	END_IF
ELSE
	rStepBias:=0;
	//清空变量
	iCountDirChange:=0;
	rAGCInit:=0;
	rAGCMaxValue:=0;
	rAGCMaxBias:=0;
	rDirection:=1;
	iCountStop1:=0;
	iCountStop2:=0;
	ton(IN:=FALSE,PT:=T#1S,Q=>,ET=>);
	//rStepBias:=0;
	rSearchNextStepTarget:=0;
	bSucess:=FALSE;
	iCountSearchRight:=0;
	bSearchRight:=FALSE;
	iCountBlockEnd:=0;
END_IF


(*
IF rStepBias< rSearchNextStepTarget THEN 
	rStepBias:=rStepBias+rStep;
ELSIF rStepBias> rSearchNextStepTarget THEN
	rStepBias:=rStepBias-rStep;
ELSE
	rStepBias:=rStepBias;
END_IF*)

(*==============================================================================
  PRG: GPRMC_1（GNSS 串口接收与 NMEA 时间解析）
  任务: SerialCom 5ms
  硬件: GCAN 模块串口 mPort=1（232），115200 8N1
  作用:
    - 读 GNSS 模块输出的 NMEA 报文（GPRMC 等，帧头 ASCII '$'=36）
    - 从固定偏移解析 UTC 日期时间，+8 转为北京时间
    - 写入 GVL.stGNSS_Timestap（毫秒 ULINT），供 TimeAdd / RealTimePosCal 使用
  下游:
    TimeAdd.icount — 秒未变时累加，用于 GNSS 丢帧时的 10ms 插值
    RealTimePosCal — GVL.dRealTime := stGNSS_Timestap + 10*TimeAdd.icount
==============================================================================*)


